) VALUES
  (1, 'race-a95973b05aac3500e9d8dcda7d519d0a9d5f18c7d44b0ff2e7bab402d1b2f258', 'Standard Human', 'From the first tools chipped from stone to the sprawling cities that touch the clouds, Standard Humans have thrived by bending without breaking. They are masters of adaptation, taking what exists and reshaping it to meet the needs of the moment. Their history is one of migration, invention, and reinvention — a constant cycle of trial and error that has forged a race capable of surviving almost anywhere. In times of peace, they build; in times of strife, they endure. They are neither the strongest nor the swiftest, neither the most cunning nor the most enduring — yet they find ways to close the gap through sheer persistence and ingenuity. Their cultures are as varied as the landscapes they inhabit, from tightly-knit village communities to sprawling multicultural metropolises. Outsiders often underestimate them because of their lack of extremes, but this very balance allows them to blend into nearly any environment. To meet a Human is to meet a puzzle of influences — traits borrowed, adapted, and made their own over generations. They excel in cooperation, forging alliances with other peoples, and in competition, driving themselves to match and surpass their peers. For all their accomplishments, they carry a restlessness that pushes them toward new horizons, sometimes at the cost of appreciating what they already have.', 'Average Height: 5′4″–6′2″; Average Weight: 120–220 lbs; Proportions: upright bipedal frame with balanced limb-to-torso ratio; Skin Color: ranges from very light to deep brown; Hair Color: black, brown, blonde, red, grey, or white; Eye Color: brown, blue, green, grey, hazel; Notable Features: none beyond normal human variation.', 'Standard Humans exhibit a wide range of appearances and presentation styles influenced by culture, climate, and personal choice. They adapt their clothing, tools, and mannerisms to circumstance, whether practical, ceremonial, or ornamental. Their presence can shift quickly to match social or environmental demands, and they carry themselves with an ease that reflects their versatility.', '15-90', 15, 90, 'Medium', 2, 'Jack of All Trades', 'First Tier-1 skill in a new Intelligence, Wisdom, or Charisma category costs 50% less XP.', 'NA', 'Common plus one additional language of choice', 'Generalist Adventurer; Diplomat; Artisan', 'Fantasy – Farmer, traveling merchant, court scribe. Sci-Fi – Starship crewman, corporate negotiator, xenolinguist. Post-Apocalyptic – Scavenger leader, community medic, salvage broker.', 'They see life as a field of open doors, each leading to new skills, alliances, or ventures. Their strength lies in versatility, but this same breadth can bring hesitation when choices are many. Humans often embrace change readily, reshaping themselves to fit new circumstances rather than resisting them. They are quick to learn from failure and equally quick to try again, rarely letting setbacks close a door for long. While they can be deeply loyal to causes or companions, they tend to value personal agency above strict tradition, seeking ways to bend the rules when they believe the outcome is worth it.', 'Humans meet the emergence of magic or new powers with a mix of curiosity, caution, and innovation. They may not master any one thing faster than others, but they will find a way to make it work for them.'),
  (2, 'race-8b97f082f93d9bae2fe3c7cb85ff083377847e37c3982a624908204000f9a6ea', 'Educated Human', 'In every era, Educated Humans have chosen the pursuit of knowledge as their path through life. Their legacy is one of meticulous study, where each generation stands on the shoulders of the last, adding to the collective memory preserved in books, archives, and now digital vaults. These are the record-keepers, the archivists, and the planners whose efforts have shaped civilizations as much as the warriors and builders. Raised in environments where learning is not just encouraged but expected, they hone their minds in lecture halls, laboratories, and debate chambers. Their communities often revolve around centers of knowledge — universities, research guilds, or think tanks — where ideas are tested, debated, and refined. They tend toward patience, preferring the slow certainty of proven methods over the gamble of improvisation. Outsiders may see them as overcautious or even aloof, but to them, careful thought is the surest path to lasting solutions. Many Educated Humans specialize so deeply in their chosen field that they risk becoming disconnected from everyday life, yet their insights can solve problems no one else could even define. They bring order to chaos through analysis, though they may falter when that chaos refuses to fit the models they know. Their presence in a community often ensures stability, foresight, and the preservation of culture for generations to come.', 'Average Height: 5′3″–6′0″; Average Weight: 110–200 lbs; Proportions: upright bipedal frame, often of average build; Skin Color: ranges from very light to deep brown; Hair Color: black, brown, blonde, red, grey, or white; Eye Color: brown, blue, green, grey, hazel; Notable Features: posture and hand use often shaped by prolonged study or sedentary work.', 'Educated Humans typically present with a deliberate, measured demeanor. Their clothing often emphasizes practicality for study or work, with tools, books, or devices close at hand. Movements tend to be precise, reflecting habits formed through detailed tasks. Their surroundings and appearance frequently signal their dedication to organized thought and information retention.', '15-90', 15, 90, 'Medium', 3, 'Ivory-Tower Recall', 'Once per session, may recall a relevant fact from prior study and roll Intelligence. On success, grant +10 to the next allied roll that uses that information.', 'On failure, overcomplicate the explanation, incurring –10 on own next roll.', 'Common; plus two scholarly languages or code systems', 'Scholar; Strategist; Researcher', 'Fantasy – Royal archivist, court wizard’s apprentice, alchemical researcher. Sci-Fi – Ship’s science officer, AI programmer, astrocartographer. Post-Apocalyptic – Historian of the old world, relic codebreaker, medic trained from salvaged manuals.', 'They approach the world as a puzzle to be solved, preferring careful planning over improvisation. Every claim demands proof, every decision rests on precedent or logic. Their disciplined thinking often allows them to see patterns others overlook, giving them an edge in problem-solving and strategic planning. However, their reliance on established methods can make them slow to adapt when the situation demands unorthodox solutions. They value knowledge as both a tool and a shield, often believing that understanding a thing is the first step toward mastering it, whether that “thing” is a trade, a conflict, or an unfamiliar world.', 'Educated Humans approach the unknown with analytical curiosity. Magic or new technologies are examined methodically before being trusted.'),
  (3, 'race-f1043a71a1fa806fb6aa5baafd40374336d108b6b2388a6d0d9b819b5fe42cbe', 'Nomadic Human', 'Nomadic Humans are wanderers by tradition, their histories written in the dust of countless roads and the logs of caravans that crossed the world’s widest reaches. Their origin lies in the meeting places between civilizations, where trade, travel, and adaptation are matters of survival. Over generations, they have mastered the art of living light — carrying only what they can repair, barter, or trade along the way. They know the routes that bind distant lands together and the hidden ways known only to those who walk them. Their culture prizes self-reliance, but also recognizes that survival on the road depends on mutual aid; a stranger one day may be a savior the next. They are storytellers and deal-makers, carrying news, goods, and ideas from one corner of the world to another. While others build walls, they map the ways around them. Their adaptability makes them skilled mediators between cultures, though some see them as rootless and unreliable. In truth, their loyalty is to the road itself and the people who travel it with them. Meeting a Nomadic Human is to meet someone shaped by the horizon — alert to opportunity, wary of traps, and always ready to move when the winds change. They are both the lifeblood of commerce and the keepers of paths others have forgotten.', 'Average Height: 5′3″–6′1″; Average Weight: 115–210 lbs; Proportions: upright bipedal frame with variable builds; Skin Color: varies widely, often reflecting mixed ancestry; Hair Color: black, brown, blonde, red, grey, or white; Eye Color: brown, blue, green, grey, hazel; Notable Features: weathering of skin and hair from frequent travel in varied climates.', 'Nomadic Humans often bear the marks of travel — sun and wind exposure, well-worn clothing, and gear adapted for portability. They carry practical equipment suited to changing environments, and their movements suggest readiness to move on short notice. Their style blends influences from multiple regions, reflecting the varied places they’ve passed through.', '15-90', 15, 90, 'Medium', 1, 'Trailblazer’s Instinct', 'Once per session, after time spent traveling or trading, may ask for the safest, fastest, or most profitable route ahead and roll Wisdom. On success, gain +10 to the next Navigation, Survival, or Networking roll tied to that path.', 'On failure, misinterpret signs and take –10 to the same check.', 'Common; plus one trade language acquired on the road', 'Pathfinder; Trader; Scout', 'Fantasy – Caravan leader, ranger, traveling bard. Sci-Fi – Interstellar merchant, asteroid prospector, cargo hauler. Post-Apocalyptic – Wasteland scout, barter-town runner, salvage convoy driver.', 'They see the world as a shifting map of opportunities and risks, where survival depends on reading the land and the people who move across it. Trust is earned through shared hardship, and promises are as binding as iron—until the wind or the road demands a change of course. Their adaptability comes from necessity, not luxury, and they measure wisdom in how well one can thrive without fixed roots. While their independence is fierce, they understand the value of temporary alliances, especially when the journey grows dangerous. Whether moving through deserts, forests, starfields, or ruins, they carry their sense of home within themselves, leaving little behind but footprints and stories.', 'They view new forces such as magic as unpredictable but potentially transformative, adapting quickly to altered landscapes and opportunities.'),
  (4, 'race-70fb16869c8e941f68d9d10148be86cf1a3382ef6336d3df55fbbaa4cb29d30a', 'Hill Dwarf', 'Hill Dwarves are the enduring craftsmen of the lowlands, where rolling hills meet exposed stone and deep quarries. Their legacy is written in bridges that have stood for centuries and hearths that have warmed a hundred winters. Unlike their mountain kin who retreat into lofty citadels, Hill Dwarves keep their settlements open to travelers, valuing trade and neighborly bonds as much as stone and mortar. Generations of quarrying, masonry, and brewing have honed their bodies into sturdy frames built for hard work and long days. They are slow to anger but slower to forgive, and their loyalty must be earned with consistent action. Pride in craft is their greatest virtue and their greatest flaw — a Hill Dwarf will labor months longer than needed if it means the work will last another lifetime. Outsiders often find them blunt to the point of rudeness, but behind their words is a commitment to honesty that borders on sacred. They are known for their barrel-aged spirits, meticulous engineering, and buildings that seem to grow stronger with age. Quick fixes and shoddy work earn nothing but contempt from them. In a world that changes quickly, they are an anchor, building not for the moment, but for the generations yet to come.', 'Average Height: 4′4″–4′10″; Average Weight: 150–200 lbs; Proportions: short, stocky frame with dense bone and muscle; Skin Color: light to medium tones, often with ruddy or earthy undertones; Hair Color: black, brown, red, grey, or white; Eye Color: brown, hazel, green, or grey; Notable Features: thick hands, strong forearms, and calloused skin from manual labor.', 'Hill Dwarves often appear sturdy and grounded, with attire suited for masonry, quarrying, or other physical crafts. Clothing is durable and practical, often showing signs of careful mending rather than replacement. Tools may be carried openly, and their movements are deliberate, reflecting endurance over haste.', '30-350', 30, 350, 'Medium', 1, 'Stone Sense', 'Up to three times per session, may focus on bedrock vibrations within 30 ft and roll Wisdom. On success, learn precise details about faults, hollows, or ore veins.', 'No penalty; simply gain no insight.', 'Common and Dwarven', 'Artisanal Mason; Whisky Cooper; Rural Civil-Works Inspector', 'Fantasy – Castle mason, fortress brewer, temple restorer. Sci-Fi – Colony habitat engineer, asteroid miner, environmental stabilizer. Post-Apocalyptic – Ruins restorer, water filtration craftsman, bunker fortifier.', 'They value steadiness over speed, believing that what lasts is worth the wait. Quick fixes earn suspicion, while a well-made wall or cask is proof of pride and skill. Hill Dwarves speak plainly, deal fairly, and measure worth in work done rather than words spoken. They take comfort in the familiar and the reliable, often finding joy in traditions that tie them to their ancestors. Though they may seem slow to act, once their mind is set they become immovable in purpose, standing as steadfast as the hills they call home.', 'Magic is another tool to them, like water pressure or a hammer’s weight. Useful if applied with care, disastrous if forced.'),
  (5, 'race-067bfc28adbb856f0d4d567844713cc6aa3fca6045eb0cf588af23e8068734ae', 'Mountain Dwarf', 'Mountain Dwarves are born to the heights, where air is thin, snow falls like shards, and the earth itself shifts underfoot. Their cities cling to cliffsides and perch above yawning valleys, held in place by rope bridges, anchor bolts, and sheer will. Centuries of living in constant danger from avalanches, rockslides, and storms have shaped them into master riggers and structural engineers. Every step is measured, every knot inspected, and every handhold tested before weight is placed upon it. Precision and preparation are cultural laws, and neglecting them is the highest form of recklessness. Their climbing harnesses and rigging systems are as much a part of their identity as their beards. Mountain Dwarves are not given to boasting until the work is done, but when they do, it is with the satisfaction of those who have defied nature and won. Outsiders often marvel at their feats, yet fail to grasp the quiet discipline that underlies every success. They can be slow to trust outsiders with dangerous work, preferring to see proof of skill before handing over a rope. To live among them is to live in constant awareness of the risks — and the thrill — of life at the edge. They have carried their craft into the modern age, turning their talents to building and maintaining structures that scrape the sky or pierce the crust of alien worlds.', 'Average Height: 4′4″–4′10″; Average Weight: 150–200 lbs; Proportions: compact, muscular frame with broad shoulders; Skin Color: light to medium tones, sometimes with a weathered or wind-burned appearance; Hair Color: black, brown, red, grey, or white; Eye Color: brown, hazel, green, or grey; Notable Features: calloused hands, rope-wear marks on skin, and musculature developed from climbing or hauling.', 'Mountain Dwarves tend toward functional clothing reinforced for climbing, construction, or extreme weather. Harnesses, ropes, and other safety gear are often kept on-person, even outside work. Their posture and movement convey balance and careful weight placement, and their gear often shows signs of meticulous upkeep.', '30-350', 30, 350, 'Medium', 1, 'Sure-Grip', 'Once per session after working in dangerous terrain, may roll Wisdom to detect impending structural or snowpack failure. On success, gain +10 to the party’s next countermeasure.', 'On failure, –10 to their first related roll.', 'Common, Dwarven, and High-Anchor Cant', 'Structural Rigger; Survivalist; Avalanche Monitor', 'Fantasy – Bridge builder, mountain guide, siege engineer. Sci-Fi – Space station hull worker, orbital tether engineer, planetary terraforming rigger. Post-Apocalyptic – Cliff settlement defender, overpass restorer, wind turbine maintainer.', 'They are methodical and precise, knowing that in their world a single loose knot or overlooked crack can kill. Reliability is a creed, redundancy a virtue, and no effort is wasted when safety and stability are on the line. Mountain Dwarves respect hierarchy born from competence and experience, but they have little patience for titles without skill to back them. To them, danger is best met with preparation, and success is a structure built layer by layer. Though their caution can make them seem reserved, it also means their commitments—once made—are as unshakable as the stone under their feet.', 'They treat magic as they do the mountain — beautiful but deadly if misread. It is reinforced with mundane safety before trust is given.'),
  (6, 'race-2945e6857e3603e0358fbf2468831cfc2237599f2c0edd3dfaca3450e67cc4c3', 'Deep Dwarf', 'Deep Dwarves are the underworld’s cartographers, navigating a labyrinth of stone and darkness few on the surface can imagine. Their earliest halls were carved in pursuit of ore and water, and over the centuries they transformed tunnels into sprawling subterranean cities. They know the sound of stone shifting in its sleep, the subtle vibrations of a distant collapse, and the perfect spot to place a support that will hold for a hundred years. Communication in the deep is often wordless — a code of taps, knocks, and vibrations that carry farther than voices. Silence is safety; noise is danger. Deep Dwarves value precision in all things, for a single misjudged blast or misplaced beam can spell disaster for an entire settlement. Outsiders often find their manner quiet and distant, but this is the reserve of those who live where one wrong move can bury a thousand lives. They have little patience for surface dwellers who underestimate the weight of stone or the value of caution. Their skill in navigating and securing tunnels makes them invaluable in times of crisis, whether clearing a collapse or reinforcing a crumbling foundation. Though they rarely seek the open sky, they will endure it for work that serves the clan or secures vital resources. To earn their trust is to be given safe passage through the world’s most dangerous depths.', 'Average Height: 4′3″–4′9″; Average Weight: 145–195 lbs; Proportions: stocky, compact build; Skin Color: pale to greyish tones, often with a cool or muted cast; Hair Color: black, grey, white, or deep brown; Eye Color: grey, pale blue, or muted green; Notable Features: light-sensitive eyes, pronounced tactile calluses on hands, and hearing adapted to faint vibrations.', 'Deep Dwarves dress for low-light work, favoring fitted gear that does not snag in tight spaces. Surfaces are often muted to avoid sound and light reflection. Movements are controlled and quiet, reflecting a lifestyle of caution in confined or unstable environments. They carry tools for sensing and stabilizing stone, and their manner is typically reserved and deliberate.', '30-350', 30, 350, 'Medium', 1, 'Sonar Tap', 'Once per session, may rhythm-tap to map surroundings and roll Wisdom. On success, gain +10 to the next allied Engineering, Navigation, or Security check using that intel.', 'On failure, misleading echoes impose –10 to their own next related roll.', 'Common, Dwarven, and Low-Rail Cant', 'Tunneler; Miner; Security Specialist', 'Fantasy – Dungeon excavator, vault guard, subterranean scout. Sci-Fi – Starship hull inspector, asteroid tunnel miner, maintenance tech for orbital cores. Post-Apocalyptic – Subway network guide, fallout shelter engineer, underground smuggler.', 'They think in echoes and vibrations, reading the world through sound and touch more than sight. Patience is their ally, and they prefer to move unseen, letting stone and shadow shield them from danger. To a Deep Dwarf, the surface is an exposed and restless place, best visited briefly before retreating to the safety of the depths. They measure trust in years, not days, and consider secrecy a form of protection rather than isolation. When they commit to action, it is with the same inevitability as a cave-in—slow to start, but unstoppable once begun.', 'Magic is a shifting force underground, capable of strengthening walls or shaking them apart. They employ it with strict caution.'),
  (7, 'race-f43af49ed64dee2c0b6b2cd1307900e2a2f524e81979d4318ab3d6920530c2ae', 'Forge Dwarf', 'Forge Dwarves are the industrial heartbeats of dwarvenkind, carrying the legacy of the anvil into the age of roaring furnaces and precision machining. Their ancestors once worked the deep forges beneath mountains, but over centuries they migrated into bustling cities where smoke stacks replaced stalactites. In their hands, ancient techniques blend seamlessly with modern tools; the clang of a hammer on steel harmonizes with the whir of lathes and the sizzle of welding arcs. They are perfectionists by nature, refusing to release a piece of work until it meets standards measured in microns. Their bodies are built for endurance, with thick arms and chests conditioned to endure long hours in sweltering heat. Forge Dwarves take pride in their ability to adapt their craft to any metal, from wrought iron to star-forged alloys, yet they hold fast to the belief that every project is a reflection of its maker’s honor. Outsiders find them intense, sometimes to the point of intimidation, but beneath the soot and gruff tone is a deep camaraderie for those who share their work ethic. Their guild halls are equal parts workshop, training ground, and family hearth, where apprentices learn both the craft and the discipline to wield it responsibly. In their eyes, a shoddy product is a stain not only on the maker but on the entire forge line. They see themselves as the keepers of quality in a world increasingly willing to cut corners, and they wear that responsibility like armor.', 'Average Height: 4′2″–4′8″; Average Weight: 160–220 lbs; Build: broad, barrel-chested, with heavily muscled forearms; Skin: shades from iron-oxide red to ash-smudged russet; Hair: thick, often short-cropped or tightly braided beards secured with heat-proof clips; Eyes: varied natural tones; Common Accessories: safety-orange goggles; Notable Features: dense musculature adapted to heat endurance.', 'Stocky, heat-hardened dwarves whose strength is written in the thick cords of their arms and the set of their shoulders. Their beards are kept practical—short or tightly braided—and their work gear is built for both protection and efficiency. Forge Dwarves often carry the scent of oil, metal, and heat, their clothes bearing faint burn marks from long hours near furnaces. Their bearing is focused and purposeful, every movement suggesting precision and practiced skill.', '30-350', 30, 350, 'Medium', 1, 'Shop-Floor Stamina', 'Up to two times per gaming session, a Forge Dwarf can enter a 10-minute “heat cycle.” The next metal-working or metal-weapon action they take (Engineering, Melee Attack, or relevant tool test) gains +10.', 'NA', 'Common, Dwarven, plus shop-floor “Machine-Code” argot', 'Precision Machinist; Foundry Quality-Control Inspector; Maker-Space Mentor', 'Fantasy – Royal armorer, master smith, siege engine crafter. Sci-Fi – Starship hull fabricator, orbital forge engineer, industrial robotics tech. Post-Apocalyptic – Scrap metal refiner, weaponsmith, settlement infrastructure builder.', 'They measure worth in precision, efficiency, and the longevity of their work. Every project is a statement of personal and clan honor, meant to endure long after the hands that shaped it are gone. Forge Dwarves respect innovation only when it strengthens the proven methods they already trust, preferring refinement over reckless invention. They are deliberate in speech and action, weighing each choice with the same care they give to the metals they temper. To them, the world is a forge—life’s trials are the hammer blows that shape character and strength.', 'Mana is just another alloying element—temper it right and a blade can sing; rush the quench and the billet warps. Forge Dwarves champion arcano-steel composites but lobby hard for safety standards lest shoddy runework sabotage sound engineering.'),
  (8, 'race-7efe6b06e7c7b87884712e76487b83b1db46564cca67e5639b02c95535e5ab1a', 'Gnome', 'Gnomes are the miniature titans of precision engineering, blending an almost obsessive curiosity with the fine motor skills of a master jeweler. Their history is rooted in artisan workshops and hidden warrens where gears and springs clicked long before the rise of modern technology. Over the centuries, they became innovators in delicate machinery, intricate clockworks, and, more recently, microcircuitry and robotics. Gnomes are rarely content with a working device — they must see if it can be made smaller, faster, or more efficient. Their minds race ahead of the present, dreaming of new designs even as they tweak the last. They are fiercely loyal to their guilds, which act as both professional networks and extended families, ensuring every creation meets strict standards. While quick to share ideas, they are protective of their best designs, guarding them with both secrecy and clever failsafes. Their small stature belies a large presence in technological advancement, with their innovations often sparking revolutions in multiple fields. Outsiders may find them eccentric, sometimes maddeningly so, but their oddities are often the byproduct of a mind juggling a dozen projects at once. A Gnome’s workshop is a chaotic wonderland of half-finished devices, blueprints pinned to every surface, and a constant background hum of whirring parts. They view their work as both craft and legacy, knowing that a single brilliant invention can change the course of history.', 'Average Height: 3′0″–3′6″; Average Weight: 40–55 lbs; Proportions: small, finely built frame with proportionally large hands for size; Skin Color: ranges from fair to medium brown; Hair Color: black, brown, blonde, red, grey, or white; Eye Color: brown, hazel, blue, or green; Notable Features: dexterous fingers, fine motor control, often slight facial creasing from focused work.', 'Gnomes tend to present in neat, functional attire suited for technical or detailed work. Their clothing often features pockets, loops, and tool holsters. They move with deliberate precision, and their surroundings may reflect a constant state of tinkering—devices in progress, diagrams, and tools within easy reach.', '20-425', 20, 425, 'Small', 1, 'Gearbound Ingenuity', 'Once per gaming session, a Gnome may roll Intelligence when tinkering with machinery or microtech. Success: next allied Engineering or Computer Operations roll that involves fine-tuning or repair gains +10.', 'A misaligned cog or data glitch imposes –10 on the Gnome’s own next relevant roll.', 'Common, Gnomish Technical Cant', 'Boutique Roboticist; Clockwork Horologist; Drone Repair Specialist', 'Fantasy – Clockwork trapmaker, royal artificer, mechanical pet breeder. Sci-Fi – Drone mechanic, AI maintenance tech, orbital robotics engineer. Post-Apocalyptic – Salvage gear rebuilder, jury-rig medic tools specialist, settlement drone operator.', 'They see invention as both a necessity and a joy, blending precision with creativity in equal measure. Curiosity drives them into the unknown, but they rarely venture there without some clever tool or trick in mind. While their ideas can seem whimsical to others, each is rooted in an instinct for problem-solving and improvement. Gnomes thrive in environments where experimentation is welcome, though they are just as capable of thriving under strict conditions by bending the rules without breaking them. Their minds are in constant motion, finding potential in scraps, missteps, and overlooked details.', 'Gnomes treat magic like a volatile upgrade—promising vast new possibilities but fraught with unpredictable side effects. Some eagerly graft arcane runes onto microcircuits; others warn that a single spell misfire could cascade through every linked device.'),
  (9, 'race-1893407afcbcaebbdc194ba48022b4a149c6cc56dcd001120e5a59c9b3db8e87', 'Tinker Gnome', 'Tinker Gnomes are the restless innovators of the gnomish world, driven less by perfection and more by the thrill of creation. Their history is marked by bursts of progress — wild, unpredictable leaps in technology spurred by late-night experiments and half-mad inspiration. They are quick with their hands and quicker with ideas, often producing gadgets before anyone can decide if they’re needed. Failure is not a deterrent; it is an expected and even celebrated part of their process. Their workshops are cluttered with prototypes, some brilliant, others dangerous, many both. Tinker Gnomes have a knack for spotting unconventional solutions, turning scrap into lifesaving tools or devastating weapons with equal ease. They are natural problem-solvers, but their solutions sometimes bring as many complications as they resolve. While they share the gnomish love for fine engineering, their work favors speed and improvisation over polish and durability. This makes them invaluable in emergencies, when a working tool right now matters more than one that will last a lifetime. Outsiders often underestimate them due to their size or whimsical demeanor, but few doubt their genius after seeing them work under pressure. They are storytellers through their machines, each invention a reflection of their boundless curiosity and refusal to accept “impossible” as an answer. In a world of constant change, Tinker Gnomes thrive, always chasing the next great idea.', 'Average Height: 3′0″–3′6″; Average Weight: 40–55 lbs; Proportions: small, compact build; Skin Color: fair to medium brown; Hair Color: black, brown, blonde, red, grey, or white; Eye Color: brown, hazel, blue, or green; Notable Features: quick hand movements, light scarring or singeing from experimental work.', 'Tinker Gnomes usually wear practical, durable clothing with signs of heavy use—burn marks, patches, or oil stains. Their gear is often improvised or modified, reflecting their fast-paced approach to problem-solving. They move with visible urgency, often carrying or wearing partially completed gadgets.', '20-425', 20, 425, 'Small', 1, 'Rapid Prototype', 'Once per gaming session, a Tinker Gnome may attempt a Rapid Prototype. Roll Intelligence. Success: their next Engineering or Computer Operations roll involving that device gains +10.', 'The jury-rigged gadget misfires, imposing –10 on their next related roll.', 'Common, Gnomish Technical Cant', 'Prototype Repair Tech; Gear Modder; Kinetic Toymaker', 'Fantasy – Siege engine tinkerer, magical trap inventor, gnomish market gadget vendor. Sci-Fi – Starship system modder, exosuit fabricator, orbital scrap engineer. Post-Apocalyptic – Wasteland gear hacker, vehicle mod shop operator, jury-rigged defense builder.', 'They believe every problem has a mechanical solution, and every failure is simply a prototype for success. Mistakes are part of the process, often celebrated as lessons rather than hidden away. Tinker Gnomes have an uncanny ability to improvise fixes with whatever is on hand, though their creations may sometimes value ingenuity over elegance. They are driven by the thrill of seeing something work for the first time, even if it requires three repairs afterward. In their hands, the line between “brilliant innovation” and “accidental chaos” is paper thin—and they wouldn’t have it any other way.', 'Tinker Gnomes treat magic as another system to reverse-engineer—ley lines become power conduits, and runes are just code to be optimized. They’re first to prototype arcane accelerators, but worry that mystical self-replicating golems could outpace even their wildest designs.'),
  (10, 'race-0698b3a4a010f9170a6fece7a5648cf375cc0694ed6017092c2d427b87d8522e', 'Trickwire Gnome', 'Trickwire Gnomes are masters of caution and calculation, blending the skills of traditional trapmakers with the cunning of modern infiltration experts. Their origins lie in the hidden warrens of fortified gnome enclaves, where securing perimeters was a matter of survival and ingenuity. Over centuries, they adapted these skills to the emerging frontiers of information warfare, treating every lock and every line of code as puzzles to be solved. They see danger as an equation—one that can always be anticipated, mitigated, or redirected. Their sharp minds and steady hands make them equally comfortable crafting delicate clockwork snares or dissecting encrypted data streams. Trickwire Gnomes rarely rush into a space without first mapping its vulnerabilities, and they leave behind security measures that are both functional and artful. Though they prize foresight over brute force, their methods are not without risk; one misread pattern can turn preparation into liability. In their own communities, they are valued as protectors, analysts, and strategic advisors. Outsiders often find them reserved, even paranoid, but those who earn their trust find an ally whose preparations can mean the difference between victory and disaster. Their legacy is one of vigilance—an unending watch over the borders, whether those are physical gates or the invisible edges of a network.', 'Average Height: 3′0″–3′6″; Average Weight: 40–55 lbs; Proportions: small frame with wiry musculature; Skin Color: fair to medium brown; Hair Color: black, brown, blonde, red, grey, or white; Eye Color: brown, hazel, blue, or green; Notable Features: calloused fingertips, fine tool wear on nails, and focused gaze.', 'Trickwire Gnomes favor fitted clothing and gear designed to minimize snags or noise. They often carry precision tools discreetly, and their posture suggests constant situational awareness. Their manner is controlled and deliberate, with careful movements that hint at a lifetime of handling fragile mechanisms or sensitive materials.', '20-425', 20, 425, 'Small', 1, 'Trapfinder’s Instinct', 'Once per gaming session, a Trickwire Gnome can sweep an area for concealed dangers. Roll Investigation. Success: detects all mundane traps or hidden devices within 30 ft and grants +10 to the party’s next Disarm Trap, Survival, or Dexterity-based check in that zone.', 'Misidentifies benign features as hazards, imposing –10 on their own first trap-related roll.', 'Common, Gnomish Technical Cant, plus Hack-Argot', 'Surveillance Tech; Trap Architect; Hacker-for-Hire', 'Fantasy – Royal vault trapwright, thieves’ guild countermeasure engineer, espionage gadgeteer. Sci-Fi – Cybersecurity infiltrator, orbital station sabotage prevention tech, drone perimeter hacker. Post-Apocalyptic – Settlement perimeter trapper, data vault intruder, scavenger route safeguard specialist.', 'They prize foresight over brute force, believing every threat has a pattern to be uncovered. Trickwire Gnomes see the world as a puzzle of cause and effect, where careful observation can unravel even the most tangled problems. Their caution is paired with creativity, allowing them to turn simple tools into elaborate safeguards or traps. While they may seem paranoid to outsiders, their readiness often means they are the last ones caught off guard. For them, victory lies in ensuring the danger never has a chance to strike at all.', 'They view magic like an unknown code: powerful, unpredictable, and full of hidden routines. Trickwire Gnomes retrofit wards into firewall logic, ever-watchful for glitches that might cascade into catastrophe.'),
  (11, 'race-8524582ece256663733d3d776ed9b7652f67494e427ba21263d56ed389867071', 'Orc', 'Orcs are the iron-bonded guardians of their people, shaped by a heritage of collective survival and disciplined strength. Their history is one of clans standing shoulder-to-shoulder against threats, forging unity in the crucible of shared adversity. Traditionally living in close-knit communities, Orcs blend martial discipline with deep-rooted communal care, ensuring no member is left behind. Their power lies not only in raw physicality but in their ability to organize, coordinate, and rally others toward a common cause. They are trained from youth to respect the strength of the group over the glory of the individual, making them formidable both in defense and in leadership roles. Orc traditions honor service to the clan—whether through farming, healing, building, or fighting—each role equally vital. Outsiders often misjudge them as aggressive or domineering, mistaking confidence for arrogance and direct speech for hostility. In truth, they value honest communication and practical solutions above all. Their rituals often combine feats of endurance with celebrations of community bonds, strengthening ties through both trial and festivity. In battle or crisis, their presence has a grounding effect, inspiring allies to stand firm and resist panic. The legacy of the Orc is one of resilience, honor, and an unshakable commitment to those who fight, work, and live beside them.', 'Average Height: 5′8″–6′4″; Average Weight: 180–260 lbs; Proportions: tall, broad-shouldered, muscular build; Skin Color: ranges from light grey to deep green-grey; Hair Color: black, dark brown, or grey; Eye Color: brown, amber, or dark green; Notable Features: pronounced jawline, muscular forearms, and heavy bone structure.', 'Orcs present with a grounded, confident stance. Clothing is often functional and durable, designed for both work and conflict. They may carry tools or weapons openly, and their movements tend toward directness and efficiency. Their overall presence conveys readiness and physical capability.', '12-60', 12, 60, 'Medium', 1, 'Iron Brotherhood', 'Once per gaming session, an Orc can invoke the Iron Brotherhood to rally their allies. Roll Charisma: Success: Grant +10 to one ally’s next Leadership or Survival roll.', 'Failure: Miscommunication sows confusion, imposing –10 on the next allied roll in that category.', 'Common plus Orcish Trade Slang', 'EMT Squad Lead; Heavy-Plant Operator; Full-Contact Sport Coach', 'Fantasy – Clan warleader, fortress healer, militia captain. Sci-Fi – Space marine sergeant, colony disaster relief coordinator, industrial mech foreman. Post-Apocalyptic – Warlord’s guard commander, survival camp medic, raider deterrence officer.', 'They value strength tempered by cooperation, believing individual power serves best when tied to the welfare of the whole. Orcs tend to view challenges as proving grounds, where skill, endurance, and loyalty are tested in equal measure. While they respect physical might, they often honor cunning strategy just as highly, seeing it as another form of strength. Bonds within their communities are deep, with shared victories and hardships forging unshakable trust. Outsiders who earn that trust find steadfast allies; those who betray it rarely get a second chance.', 'Orcs view magic as elemental power—potent when bound by runic ritual, perilous when wielded for personal gain. Many clans forge protective wards into their halls, ensuring the arcane serves the community, not the individual.'),
  (12, 'race-fc053386acecca1065cdee8320419d4d73e573cec631a9636350354ce4d1c972', 'Half-Orc', 'Half-Orcs are the living bridges between worlds, bearing the endurance and presence of their orcish heritage tempered by the adaptability and nuance of their human lineage. Their history is one of mediation, often serving as go-betweens for two cultures with very different values and perspectives. While some grow up straddling both societies, others find themselves outsiders to each, forging their own identity through a mix of learned traditions and personal philosophy. This dual heritage grants them a breadth of experience and a flexibility of thought that make them exceptional negotiators and problem-solvers. They are resilient in the face of social and physical challenges alike, with a deep understanding of the power—and the cost—of compromise. In conflict, they often act as the voice of reason, though they can fight with ferocity when pushed to defend what matters. Many develop a natural talent for reading people, able to sense tensions before they boil over. This ability, combined with their physical capability, allows them to navigate roles that demand both strength and diplomacy. Outsiders often project their own assumptions onto Half-Orcs, seeing them as too orcish or too human, yet rarely understanding the strength in being both. They tend to value loyalty to individuals over allegiance to abstract ideals, making them steadfast allies but cautious joiners of causes. Their legacy is one of connection, resilience, and the ability to see the world through more than one lens.', 'Average Height: 5′6″–6′2″; Average Weight: 160–240 lbs; Proportions: strong, upright frame combining orcish muscularity with human proportions; Skin Color: light grey to medium brown with green or grey undertones; Hair Color: black, dark brown, or grey; Eye Color: brown, green, or hazel; Notable Features: slightly pronounced canines, solid musculature, and broad hands.', 'Half-Orcs often blend elements from different cultural styles in their clothing and gear. They tend to favor practical outfits with a balance between mobility and protection. Their posture reflects confidence and alertness, and they often maintain direct eye contact during conversation.', '14-80', 14, 80, 'Medium', 1, 'Enduring Mediation', 'Once per gaming session, after spending at least 15 minutes facilitating dialogue between two parties, a Half-Orc may roll Charisma: Success: Both sides grant +10 to their next Persuasion or Deception roll in that negotiation.', 'Failure: A subtle miscommunication breeds resentment, imposing –10 to the Half-Orc’s next Charisma-based roll.', 'Common, Orcish', 'Crisis Negotiator; Union Organizer; Wilderness Courier', 'Fantasy – Diplomatic envoy, borderland sheriff, interclan mediator. Sci-Fi – Corporate dispute arbitrator, multi-species alliance liaison, crisis comms officer. Post-Apocalyptic – Neutral zone peacekeeper, trade caravan negotiator, alliance broker.', 'They approach challenges with praG.O.Datic compromise, seeking solutions that serve the greatest good without forsaking principle. Half-Orcs often navigate between cultures, giving them a broad perspective on differing values and customs. This duality makes them adaptable diplomats or negotiators, though it can also mean they are viewed with suspicion by both sides. They are skilled at weighing when to stand firm and when to yield, understanding that survival sometimes depends on flexibility. At their best, they bridge divides; at their worst, they may feel as though they belong to neither world.', 'They view magic’s resurgence as another high-stakes negotiation—one that demands skilled mediators. Half-Orcs embed with multiple factions, ensuring no side is left voiceless as the arcane tide rises.'),
  (13, 'race-f59ddf918f384a1b7e1d1011c49c3f3fd38421fc3ed3d90dfaa9bb1633325478', 'Goblin', 'Goblins are the opportunists of the undercity, thriving in the forgotten places where refuse and opportunity mingle. Their history is one of scavenging and improvisation, making the most out of what others overlook or discard. In their warren-like communities, they develop intricate networks for sharing information on salvage sites, trade routes, and hidden passages. Goblins value speed of thought and adaptability over brute strength, constantly shifting strategies to match the situation. They are quick learners, often mastering the basics of new technologies or systems just long enough to exploit them for gain. Outsiders often mistake their disorganized appearance for chaos, but beneath it lies a hive-like efficiency driven by communal knowledge sharing. Their agility and knack for turning scraps into tools make them valuable in roles that demand resourcefulness. While distrustful of formal authority, Goblins excel at building their own systems of order, often revolving around mutual benefit and swift trade. They navigate tight spaces and complex social webs with equal skill, always aware of escape routes and fallback options. For them, every derelict building or abandoned ship hull is not just debris—it’s potential profit, shelter, and advantage.', 'Average Height: 3′2″–4′0″; Average Weight: 45–70 lbs; Proportions: small, lean frame; Skin Color: green, grey-green, or yellow-green; Hair Color: black, brown, or dark grey; Eye Color: yellow, amber, or red; Notable Features: long fingers, sharp facial features, and slightly pointed ears.', 'Goblins typically wear scavenged or mismatched clothing, adapted for ease of movement and quick escapes. Their gear is often assembled from salvaged parts, and they move with quick, darting motions. Their appearance is utilitarian, with practicality taking precedence over uniformity.', '10-55', 10, 55, 'Small', 1, 'Scavenger’s Foresight', 'Once per gaming session, after surveying an abandoned site or scrap heap, a Goblin may roll Intelligence. Success: They pinpoint the most valuable salvage or optimal escape route, granting +10 to the party’s next Engineering, Computer Operations, or Survival roll tied to that site.', 'Failure: They misjudge the haul or route, imposing –10 on their own next relevant roll.', 'Common, Goblin Cant, plus one local undercity argot', 'Logistics AI Tech; Scrapyard Assessor; 24-Hr Convenience Owner', 'Fantasy – Ruins scavenger, dungeon trap salvager, back-alley broker. Sci-Fi – Space hulk dismantler, orbital junkyard foreman, cargo routing specialist. Post-Apocalyptic – Wreckage recycler, salvage convoy scout, black-market parts trader.', 'They thrive on adaptability and quick thinking, seeing value where others see only waste. Goblins are masters of turning scraps into solutions, whether that means tools, weapons, or unconventional strategies. Their resourcefulness often springs from necessity, shaped by a history of surviving in harsh or neglected places. While some see them as opportunists, Goblins take pride in their ability to make the most of whatever they have at hand. To them, cleverness is as much a survival trait as speed or stealth.', 'Magic is just another salvage stream—spirit-infused castoffs are prime targets. Goblins rapidly repurpose arcane relics into hive-networked scrap economies, ever eager for the next mystic flash flood.'),
  (14, 'race-e87c60c036bec2093ff23f6f34bf9fec81165221a98d3f60bb6df3a6e8d2bbd2', 'Hob-Kin', 'Hob-Kin are the regimented cousins of goblins, favoring structure and efficiency over chaotic improvisation. Their roots trace back to warren communities that embraced order as a means of survival in densely packed environments. Every member of a Hob-Kin settlement has a role, and every role is performed with precision, whether in farming, defense, or infrastructure maintenance. They are known for their synchronized workflows, often moving in perfect unison during communal tasks or patrols. This discipline is instilled from youth, with training focused on both physical readiness and mental alertness. While they share the goblin gift for adaptation, they channel it through coordinated effort rather than individual improvisation. Outsiders often mistake their rigid schedules for inflexibility, but in truth, Hob-Kin can pivot quickly—provided the change is agreed upon and executed collectively. Their communities are marked by meticulous record-keeping, strict resource management, and mutual accountability. This structured life fosters strong bonds of trust and predictability, ensuring that every Hob-Kin can rely on their peers without hesitation. To them, efficiency is both survival strategy and cultural identity, and they wear it as a badge of pride.', 'Average Height: 3′0″–4′0″; Average Weight: 60–90 lbs; Proportions: lean frame with defined musculature; Skin Color: pale green; Hair Color: black, brown, dark grey; Eye Color: brown, amber, or green; Notable Features: regiment tattoos, low-light adapted vision.', 'Hob-Kin present with neat, functional clothing suited for communal work or patrol duties. Their movements are often synchronized in group settings, and they maintain a tidy, orderly appearance. Equipment is well-kept, with signs of regular maintenance, reflecting their preference for discipline and coordination.', '10-55', 10, 55, 'Small', 1, 'Line-Worker’s Rhythm', 'Once per gaming session, a Hob-Kin may roll Wisdom when performing any repetitive or synchronized task. Success: They optimize the workflow, granting +10 to the next allied Tactical Planning or Engineering roll.', 'Failure: They overcorrect the timing, suffering –10 on their own next roll in that task.', 'Common, Goblin Cant, plus Warrenspeak', 'Warehouse Flow Manager; Private Security Captain; City Code-Enforcer', 'Fantasy – Tunnel guard captain, fortress quartermaster, supply chain overseer. Sci-Fi – Cargo bay foreman, station security supervisor, orbital dock scheduler. Post-Apocalyptic – Bunker logistics chief, convoy security lead, fortified farm coordinator.', 'They value order, discipline, and mutual reliability, believing the group’s strength comes from perfect coordination. Hob-Kin communities often function like well-oiled machines, with each member understanding their role and trusting others to fulfill theirs. This focus on unity makes them formidable in collective efforts, whether building, defending, or governing. They are not quick to trust outsiders, but once someone proves their commitment to the group’s welfare, that loyalty is returned in full. In their view, the individual exists to serve the whole—and the whole exists to protect the individual.', 'Magic is a variable force—dangerous if unregulated. Hob-Kin champion runic protocols and magical SOPs (Standard Operating Procedures) to integrate arcane workstreams safely.'),
  (15, 'race-dd6288bff15542e93d69089b23e182ca1125092f8d62a28c755e7e57f69798bd', 'Kobold', 'Kobolds are heat-hardened specialists, descended from reptilian tunnel-dwellers who learned to thrive in the sweltering environments of volcanic vents and industrial furnaces. Their history is one of service and precision, often maintaining the very systems that others depend on but cannot endure. Kobolds excel in confined spaces where heat and pressure would overwhelm most species, using their natural resilience and acute awareness to keep complex networks running smoothly. Their culture prizes meticulous craftsmanship, with every sealed vent and calibrated conduit a testament to clan pride. These small yet capable workers navigate their maze-like warrens with instinctive ease, memorizing routes and system layouts through both sight and touch. While fiercely loyal to their crews, they are cautious in extending trust beyond them, preferring relationships built over years of consistent reliability. Outsiders often underestimate them due to their size, only to be surprised by their stamina and expertise under grueling conditions. Kobolds see their work as both survival and legacy, knowing that a single mistake in their environment could be catastrophic. For them, every day is a balance of risk and reward, and they wear their heat-born endurance as a mark of honor.', 'Average Height: 2′4″–3′2″; Average Weight: 30–50 lbs; Proportions: slender build; Skin Color: scaled, ranging from charcoal to ember red; Hair: none; Eye Color: faint orange glow in darkness; Notable Features: fine claws, heat-tolerant scales.', 'Kobolds typically wear lightweight, heat-resistant clothing and gear suited to confined spaces. Their movements are efficient and deliberate, with tools kept close at hand. Their overall presentation suggests readiness for work in extreme or hazardous environments.', '8-55', 8, 55, 'Small', 1, 'Thermal Endurance', 'Once per gaming session under extreme heat or in confined spaces, a Kobold may roll Constitution: Success: Gain +10 to the next Engineering or Survival roll.', 'Failure: Overheat isolation backfires—suffer –10 on the next Constitution or Survival roll.', 'Common, Draconic Trade Pidgin', 'Fiber-Optic Puller; Geothermal Plant Tech; Utility Crawl-Team', 'Fantasy – Volcano forgemaster, dragon’s lair tender, under-mountain vent engineer. Sci-Fi – Starship reactor tech, orbital fusion plant engineer, asteroid mining shaft foreman. Post-Apocalyptic – Geothermal plant restorer, subterranean heat grid mechanic, bunker ventilation specialist.', 'They value precision and loyalty, believing that discipline in dangerous environments ensures survival. Kobolds are careful planners, often mapping out every step before acting, whether they are building, tunneling, or setting an ambush. Their small stature belies a deep sense of purpose, and they take pride in work that others might overlook. Trust is given slowly but kept fiercely, and betrayal is rarely forgiven. While they may prefer to remain unseen, those who underestimate their determination often regret it.', 'Kobolds regard magic as a volatile energy source—potentially harnessable like geothermal heat if contained. They approach arcane anomalies with praG.O.Datic caution, eager to blueprint wards as efficiently as they seal vent valves.'),
  (16, 'race-34d508efff2f99ab1e110918f80eb1767a3f7c7fe73d03c869aae7318481805d', 'Troll-Kin', 'Troll-Kin are the living bulwarks of labor and industry, their bodies adapted to bear crushing weights and withstand punishing conditions. Descended from clans that built the oldest bridges, quarried the hardest stone, and hauled the heaviest loads, their culture prizes endurance above all. The mottled stone-like plates that cover their bodies are more than protection—they are a visible badge of work done and burdens borne. Troll-Kin are patient workers, moving with deliberate care to avoid costly mistakes. They value steady, communal effort over showy displays of speed or strength, believing that a team that works in harmony can move mountains. Honor is earned by shouldering the hard jobs without complaint, and memory is long for those who shirk their duty. Outsiders sometimes misinterpret their quiet focus for dullness, but those who work alongside Troll-Kin learn that they see far more than they say, and that their measured words carry weight. Their lives revolve around the structures they help raise—be it a dam, a cargo ship, or a fortified wall—each a testament to their place in the world. Troll-Kin prefer practical tools and proven methods over untested innovations, though they will adopt new techniques if convinced they will hold up under strain. Their legacy is one of endurance, reliability, and the unshakable strength of a foundation built to last.', 'Average Height: 6′4″–7′2″; Average Weight: 250–350 lbs; Proportions: massive frame with thick, dense bone structure; Skin Color: mottled grey; Hair Color: sparse and coarse, dark or grey; Eye Color: brown, dark green, or grey; Notable Features: plate-like dermal armor, knobby joints.', 'Troll-Kin favor durable clothing and tools sized for heavy labor. They move slowly but with great strength and stability, often carrying or wearing equipment suited to construction or hauling. Their presence is imposing, with an appearance that emphasizes resilience and endurance.', '18-120', 18, 120, 'Large', 1, 'Stonehide Resilience', 'Once per gaming session after sustaining nonlethal physical strain, a Troll-Kin may roll Constitution: Success: Reduce all damage taken by 10 on the next bruise-inducing attack or labor check.', 'Failure: Overexertion causes strain—suffer –10 on the next Strength or Survival roll.', 'Common, Orcish Trade Jargon', 'Bridge Demolition Specialist; Riot-Buffer Shield; Break-Bulk Cargo Handler', 'Fantasy – Castle wall builder, siege engine hauler, quarry foreman. Sci-Fi – Starship hull loader, asteroid mining lifter, orbital freight handler. Post-Apocalyptic – Bridge repair laborer, barricade constructor, salvage crane operator.', 'They value collective effort, quiet resilience, and the satisfaction of a job done right. Troll-Kin are patient workers who see little need to rush, confident that steady progress will outlast frantic haste. They have a practical way of looking at the world, often favoring what can be touched, built, or repaired over abstract theories. While slow to anger, once roused they can be relentless, holding to a task—or a grudge—until it is resolved. To them, strength is measured less by speed than by the ability to endure.', 'They view magic’s return as another force of nature—potentially harnessable for heavy-lift spells or protective wards, but untrustworthy until tested.'),
  (17, 'race-a22350d09c8b4d047e8249cf3ee81d2c7793db6c2f6327ee93d89d42fdc3efc5', 'High Elf', 'High Elves are the inheritors of a courtly tradition where grace, precision, and aesthetics are interwoven into every aspect of life. For centuries, they lived in gleaming citadels where diplomacy was an art form and beauty was seen as a moral imperative. Their history is a tapestry of carefully negotiated alliances, cultural patronage, and the meticulous preservation of high ritual. High Elves train from youth in the subtleties of etiquette, the persuasive power of performance, and the unspoken weight of posture and poise. To them, every interaction is a stage and every word a brushstroke in a larger portrait of influence. While this upbringing grants them an almost supernatural composure, it also makes them vulnerable to environments where raw practicality trumps refinement. High Elves see themselves as stewards of culture, charged with elevating the world around them through art, architecture, and diplomacy. They are often accused of arrogance, though they view it as confidence in centuries of cultivated skill. In modern times, they adapt these talents to new arenas, from luxury design to interstellar diplomacy, always ensuring the traditions of their people endure. Their salons and galleries serve as both cultural beacons and political staging grounds, where appearances are as vital as outcomes. High Elves believe beauty can mend division, but they never forget that beauty can also be a weapon.', 'Average Height: 5′6″–6′5″; Average Weight: 110–190 lbs; Proportions: tall, slender frame; Skin Color: alabaster to sun-kissed; Hair Color: silver, gold, platinum, or pale blond; Eye Color: luminous shades of blue, green, or gold; Notable Features: smooth skin, refined facial symmetry.', 'High Elves tend toward elegant attire, often tailored and ornamented with fine detailing. Posture is upright and composed, and movement is measured. Their grooming is meticulous, and accessories or garments may carry subtle symbolic motifs.', '25-750', 25, 750, 'Medium', 3, 'Flawless Flourish', 'Once per gaming session, after delivering a formal greeting, reveal, or artistic showcase, a High Elf may roll Charisma to “own the room.” Success: +10 to the next allied Persuasion, Deception, or Performance roll that leverages that impression.', 'Failure: Over-embellishment causes –10 on their own next social roll.', 'Common, Elven High-Cant, plus one cultivated tongue', 'Luxury Designer; Diplomatic Envoy; Couture Marketer', 'Fantasy – Court advisor, bardic ambassador, master artisan. Sci-Fi – Diplomatic protocol officer, luxury habitat designer, cultural liaison. Post-Apocalyptic – Restorationist envoy, artistic propagandist, treaty broker.', 'They see the world as a gallery where every gesture and choice is part of a greater work. High Elves tend to seek refinement in all things, whether in art, craft, thought, or action. Their long lifespans encourage them to consider the long-term consequences of every decision, weighing not just what is gained but what might be lost. While they can seem aloof, this is often a result of their tendency to observe before acting. They believe that true influence is quiet but lasting, like brushstrokes on a vast canvas.', 'Arcane resurgence is the ultimate patron—new piG.O.Dents, new protocols, new canvases. Yet High Elves fear raw magic’s unpredictability and lobby for its careful regulation.'),
  (18, 'race-c9a007727c733f41827991e81f15c49d32f9f46c718416b5e064277c5f3bfd96', 'Gold Elf', 'Gold Elves are the merchant princes and economic architects of elvenkind, descended from lineages that turned trade into both art and science. Their legacy is one of caravans laden with treasures, markets humming with negotiation, and contracts sealed with runes as binding as any oath. For them, commerce is more than profit—it is a stabilizing force that fosters peace and prosperity when conducted with integrity. Gold Elves are raised to read the subtleties of supply and demand as fluently as others read letters, and to see opportunity in every shift of fortune. Their culture prizes negotiation, adaptability, and the careful management of risk. They are consummate networkers, building webs of relationships that can span continents or star systems. While some view their focus on wealth as greed, Gold Elves counter that fair trade and mutual benefit are the cornerstones of civilization. They excel in settings where information, resources, and timing intersect, making them formidable dealmakers and strategic planners. Gold Elves are as comfortable in the opulence of trade halls as they are at the edge of a frontier market, always looking to balance the ledger. In their eyes, instability is both danger and opportunity, and they work tirelessly to turn chaos into calculated gain. Their enduring legacy is the belief that prosperity, properly managed, benefits all.', 'Average Height: 5′5″–6′4″; Average Weight: 105–185 lbs; Proportions: tall, lean frame; Skin Color: warm honey to burnished bronze; Hair Color: metallic gold or copper tones; Eye Color: brown, amber, or gold-flecked; Notable Features: facial symmetry with warm undertones.', 'Gold Elves present in finely made clothing that balances style with practicality, often incorporating subtle markers of trade or status. They carry themselves with poise and tend toward confident, open gestures when engaging with others.', '25-750', 25, 750, 'Medium', 3, 'Market Augury', 'Once per gaming session, after studying contracts, commodities data, or faction rumors for at least ten minutes, a Gold Elf may roll Intelligence to forecast a near-term market or diplomatic shift. Success: They (or a chosen ally) gain +10 to the next Networking, Persuasion, or Innovation roll tied to that forecast.', 'Failure: Misread omens impose –10 on their own next commerce-related roll.', 'Common, Elven High-Cant, plus Trade-Tongue', 'Commodities Broker; Fair-Trade Exporter; Boutique Venture Fund Partner', 'Fantasy – Merchant guildmaster, trade envoy, artifact broker. Sci-Fi – Interstellar commodities trader, station supply director, corporate strategist. Post-Apocalyptic – Black-market economist, resource broker, salvage exchange chief.', 'They value stability through commerce, seeing trade as the lifeblood of civilization. Gold Elves excel at building and maintaining networks of mutual benefit, whether through markets, diplomacy, or resource management. Their reputation for fairness in dealings is a point of pride, though they are no strangers to hard bargaining. To them, prosperity is a shared endeavor—one that grows strongest when all parties honor their agreements. While they can be praG.O.Datic in business, they see wealth as a means to strengthen and enrich their communities.', 'Magic is volatility incarnate—and volatility equals profit if hedged well. Gold Elves lobby for transparent mana indices, fearing black-market manipulation could crash both wallets and worlds.'),
  (19, 'race-4addbbce50317d9b7a76cfa78e9d3cea3880dfd7928e43e22f7ab1f220513158', 'Wild Elf', 'Wild Elves are the keepers of the living world, descended from forest guardians who learned to weave their survival with the cycles of nature. Their heritage stretches back to eras when their people lived entirely beneath the canopy, moving with the migrations of beasts and the blooming of sacred groves. Over time, they became masters of harmonizing natural rhythms with evolving tools—be it bowstring, herbal poultice, or biome drone. Wild Elves believe nature is not a resource to be consumed but a partner to be courted and respected. They are equally at home stalking game in shadowed woods or coaxing rooftop gardens to thrive in the heart of sprawling cities. Their deep connection to living systems makes them adept at reading environmental signs, tracking subtle changes that others overlook. Outsiders often romanticize them as simple woodland wanderers, but their relationship with nature is as much science as it is spirituality. They are patient, but decisive when ecosystems are threatened, and will act with fierce precision to defend them. Wild Elves see themselves as healers of the balance—restoring what has been stripped away and nurturing growth wherever they tread. Their legacy is one of stewardship, adaptability, and the blending of wild instinct with crafted innovation.', 'Average Height: 5′5″–6′0″; Average Weight: 110–160 lbs; Proportions: lean, athletic build; Skin Color: light to medium with green tattoos; Hair Color: natural shades with vine-patterned weaves; Eye Color: green, hazel, or brown; Notable Features: intricate skin markings, often leaf-themed.', 'Wild Elves favor functional clothing in natural tones, often incorporating plant-based materials or accessories. Their movements are fluid and deliberate, and they may carry tools or gear adapted to both wilderness and urban greenery.', '25-750', 25, 750, 'Medium', 3, 'Symbiotic Resonance', 'Once per gaming session in a natural or overgrown environment, a Wild Elf may roll Wisdom: Success: They harmonize biome tech and flora—gain +10 to the next Animal Handling, Survival, or Computer Operations roll that leverages living systems.', 'Failure: The signal goes awry—incur –10 on their next related roll.', 'Common, Elven High-Cant, plus Sylvan', 'Urban Canopy Climber; Wildlife Drone Ranger; Eco-Tour Guide', 'Fantasy – Forest guardian, herbalist marksman, druidic scout. Sci-Fi – Biosphere engineer, orbital garden ranger, xenobotanical researcher. Post-Apocalyptic – Wasteland reclaimer, green zone defender, seed vault courier.', 'They value harmony with the environment, seeing technology and nature as partners rather than adversaries. Wild Elves live with an awareness of the cycles that sustain life, from the smallest growth to the largest migrations. They are quick to adapt their tools and traditions to shifting seasons or new surroundings, believing flexibility is key to survival. Outsiders may find them elusive, but those who earn their respect often find themselves welcomed into a network of shared resources and quiet guardianship. To them, progress is not measured by conquest, but by the balance maintained between taking and giving back.', 'They embrace arcane resurgence as a force of growth—magical mana meets chlorophyll in their living labs.'),
  (20, 'race-f25fa5c921bc63ba74e38476cf2e976028e4bba0745235b02c773551199ac872', 'Grey Elf', 'Grey Elves walk the borders between worlds—geographic, political, and moral. Their lineage blends the blood of Dark Elves and Harbinger Elves, producing individuals with a unique aptitude for mediation and understanding. From their earliest days, Grey Elves are immersed in languages, codes, and the delicate art of balancing opposing forces. Their settlements often lie at fracture points—border towns where factions meet, post-war capitals where truces are tested, and ports where embargo lines shift with the tides. Grey Elves believe stability is forged through deliberate compromise, not dominance, and they approach every conflict as a puzzle to be solved rather than a battle to be won. Their keen insight into motives and meaning allows them to bridge gaps where others see only impassable divides. Outsiders may view them as overly cautious or unwilling to take sides, but this neutrality is a chosen discipline, not indecision. Grey Elves carry the weight of history in their negotiations, knowing that a single word can spark or prevent disaster. Their legacy is one of quiet influence, of treaties signed in candlelit rooms and crises defused before they ignite. They are as much archivists of promises as they are guardians of peace.', 'Average Height: 5′4″–6′0″; Average Weight: 110–200 lbs; Proportions: slender to medium build; Skin Color: silvery-ashen; Hair Color: dusk-white to charcoal; Eye Color: violet or steel; Notable Features: attire combining formal tailoring with functional layers.', 'Grey Elves dress with a balance of refinement and practicality, often layering garments for adaptability in varied environments. Their bearing is calm and deliberate, and their expressions tend toward measured neutrality. They maintain a composed posture, with accessories and clothing reflecting cultural ties to negotiation and mediation.', '25-750', 25, 750, 'Medium', 3, 'Edgewalker’s Poise', 'Once per gaming session, a Grey Elf may roll Wisdom to remain unfazed in a moral or tactical stalemate. Success: +10 to the party’s next Persuasion, Deception, or Intimidating Presence roll in that situation.', 'Failure: –10 on their own next attempt instead.', 'Common, Elven High-Cant, Under-Cant, plus one conflict-zone dialect', 'Multi-Species Mediator; Forensic Linguist; NGO Field Lead', 'Fantasy – Border emissary, royal codebreaker, neutral city magistrate. Sci-Fi – Interstellar treaty negotiator, cryptographic analyst, cross-species trade envoy. Post-Apocalyptic – Peace zone arbiter, underground network coordinator, alliance documenter.', 'They value equilibrium and understanding, seeing diplomacy as the highest form of defense. Grey Elves are deliberate in their decisions, often taking the time to see all sides before acting. They have a talent for finding common ground, even between bitter rivals, and consider a peaceful solution the mark of true wisdom. Yet they are not naive—when pushed, they will defend their balance with calculated precision. To them, every conflict is an opportunity to weave stronger connections, provided one listens as much as they speak.', 'They greet magic’s resurgence as new grammar in the language of power—and fear the silences it may also enforce.'),
  (21, 'race-0879ca7a173d140225b4ca8bb4ac5a7f5e6b17f55b62402d75f7ae175bec6111', 'Harbinger Elf', 'Harbinger Elves are born beneath omens—marked from birth as heralds of change. Whether seen as a blessing or a burden, this destiny shapes their lives from the first breath. Raised with the expectation that they will one day stand at the fulcrum of history, they are trained in tactics, diplomacy, and the art of preparation. Harbinger Elves believe in meeting fate with readiness, not resignation; every drill, every study, is a step toward meeting the moment they were born for. Their communities revere them as both protectors and prognosticators, though some see them as living reminders of inevitable hardship. Harbinger Elves often carry the weight of foresight alone, knowing that to speak too plainly of what is to come can shape it in unforeseen ways. They are adept at reading patterns in events, finding the threads that connect present actions to future consequences. Outsiders often mistake their calm for detachment, but it is the stillness of someone who has rehearsed the storm a thousand times. While they cannot choose the shape of the upheaval they herald, they can choose how they meet it—and who stands with them when it arrives. Their legacy is one of vigilance, discipline, and the belief that destiny is best served by those who prepare for it.', 'Average Height: 5′4″–6′0″; Average Weight: 110–200 lbs; Proportions: lean, high-metabolism build; Skin Color: light to medium with natural tones; Hair Color: various natural shades; Eye Color: flashes of faint gold during heightened emotion or omen events; Notable Features: ritual scar-runes on forearms.', 'Harbinger Elves favor functional, well-maintained gear, often accompanied by subtle insignia or symbols of readiness. Their attire tends toward clean lines with minimal ornamentation, designed for ease of movement. They carry themselves with controlled poise, projecting a sense of preparedness.', '25-750', 25, 750, 'Medium', 4, 'Foreshadowed Insight', 'Once per session a Harbinger may pose a single tactical question about an imminent danger. Roll WIS: Success: answer grants +10 to the party’s next Perception, Investigation, or Tactical Planning roll tied to that threat.', 'Failure: Conflicting futures blur vision; –10 on their own next related roll.', 'Common, Elven High-Cant, and terse War-Sigil sign-code', 'Disaster Response Coordinator; Risk Intelligence Analyst; Military Liaison Officer', 'Fantasy – War council strategist, prophetic knight, frontier watch commander. Sci-Fi – Crisis management officer, fleet readiness coordinator, planetary evacuation planner. Post-Apocalyptic – Disaster drill captain, hazard zone scout, community survival planner.', 'They value preparedness above all, seeing every day as an opportunity to train for the unknown. Harbinger Elves believe that forewarning is half of victory and maintain a watchful eye for signs others might dismiss. Their lives often revolve around rituals of readiness, from maintaining gear to rehearsing battle formations or escape routes. While some view their constant vigilance as grim, they see it as simple prudence in a world where change can arrive without warning. To them, survival is not luck—it is the reward for foresight.', 'Where others see miracle or menace, Harbingers see a timetable. They ask not if the storm comes—only who will stand ready when it breaks.'),
  (22, 'race-50d920ef0f35ca0a6477c8ac98936bb991f04e9decb56e450c30a00172c9b4dd', 'Night Elf', 'Night Elves are the unseen custodians of shadow and information, moving through the world’s darker places with the precision of a whisper. Their heritage stems from clans that patrolled moonless forests and deep alleys, where silence was survival and vision came in shades beyond ordinary sight. Over generations, they have blended these traditions with mastery over emerging technologies, making them equally at home in the digital shadows of a network or the pitch-black corners of a forgotten street. To them, darkness is not absence but a rich medium in which to work—a place of privacy, concealment, and quiet communication. They value trust and mutual obligation above all, for one loose word or misplaced light can compromise an entire network. Outsiders often imagine them as cold or paranoid, yet those who earn their confidence discover a warm, tightly woven community. Night Elves understand that visibility is vulnerability, and they have perfected the art of minimizing their footprint in both the physical and digital worlds. Their legacy is one of guardianship, safeguarding the unseen connections and quiet pathways that keep a city alive after dusk. In their eyes, every shadow is a potential ally, every packet of data a whisper in the right ear.', 'Average Height: 5′6″–6′4″; Average Weight: 120–180 lbs; Proportions: lean, sinewy build; Skin Color: midnight-blue shifting toward charcoal in bright light; Hair Color: dark shades; Eye Color: faint violet glow in darkness; Notable Features: low-light adapted vision.', 'Night Elves wear muted, non-reflective clothing suited to low-visibility environments. Movements are quiet and precise, with minimal extraneous motion. They often carry compact, easily concealed tools or gear, arranged for silent access.', '25-750', 25, 750, 'Medium', 3, 'Shadowdancer Protocol', 'Once per gaming session in dim or no light, a Night Elf may roll Dexterity: Success: Become effectively invisible for 1 minute or 1 combat step.', 'Failure: A misstep betrays their presence—suffer –10 on their next Stealth or Technology roll.', 'Common, Elven High-Cant, Infra-Lore', 'Cybersecurity Red-Team; Grave-Shift Server Tech; Stealth Courier', 'Fantasy – Shadow scout, infiltration mage, clandestine courier. Sci-Fi – Black ops data-runner, server vault infiltrator, stealth hacker. Post-Apocalyptic – Night watch sniper, darkzone smuggler, signal ghost.', 'They value secrecy, precision, and the preservation of hidden networks of trust. Night Elves prefer to act unseen, often working from the shadows to influence events without drawing attention to themselves. They are careful with their words and even more careful with their promises, keeping both only when they are certain of the outcome. Patience is a core virtue, allowing them to wait for the perfect moment to act. While they may seem distant to outsiders, their bonds within trusted circles run deep and unshakable.', 'They see magic’s resurgence as another system to integrate—new protocols to decrypt, vulnerabilities to exploit, and permissions to manage.'),
  (23, 'race-66758cb1deec2049368f04848e37523e1cfc9367dd4594d4cabb1ba322c548d6', 'Dark Elf', 'Dark Elves are masters of the underworld—both the subterranean labyrinths beneath the earth and the quiet economies of secrecy and trust. Their history is written in the tunnels they have carved and the glow of their bioluminescent tattoos, each pattern a story, a ward, or a warning. Generations of life underground have honed their senses beyond the reach of sunlight, teaching them to navigate by vibration, air current, and subtle shifts in temperature. They are patient strategists, as comfortable waiting in the shadows for the right moment to act as they are in striking quickly when opportunity demands. Dark Elves prize loyalty above all, for in the deep places, betrayal can be fatal. Outsiders often misjudge them as reclusive or treacherous, but their caution is born of necessity, not malice. They trade in rare goods—fungi, minerals, toxins, and antidotes—moving through networks of trust and whispered agreements. Their legacy is one of survival in extreme environments, of turning darkness into a domain rather than a limitation. To meet a Dark Elf is to meet someone who has lived their life with patience, calculation, and an unblinking awareness of danger.', 'Average Height: 5′2″–6′0″; Average Weight: 100–180 lbs; Proportions: slender, sinewy build; Skin Color: pale slate to obsidian; Hair Color: dark or silver; Eye Color: various with phosphorescent flecks; Notable Features: bioluminescent tattoos, phosphor-rimmed eyes.', 'Dark Elves typically wear fitted garments adapted for underground environments, often incorporating protective layers against moisture and debris. Their tattoos may emit a soft glow in dim light, and they carry themselves with deliberate, measured movement. Equipment is compact and organized for utility in confined or low-light spaces.', '25-750', 25, 750, 'Medium', 3, 'Tattooed Luminescence', 'Once per gaming session in darkness or dim conditions, a Dark Elf may roll Intelligence: Success: Tattoos glow, granting +10 to the next Investigation or Survival roll tied to environmental clues.', 'Failure: Reaction backfires—impose –10 on their own next Perception or Stealth roll.', 'Common, Under-Cant, plus one regional dialect or trade tongue', 'Biochem Lab Tech; Glow-Microbrew Crafter; Abandoned-Tunnel Mapper', 'Fantasy – Deep cavern ranger, toxin master, underground diplomat. Sci-Fi – Reactor core maintenance tech, luminescent biotech specialist, deep habitat security. Post-Apocalyptic – Tunnel salvage scout, darkzone biochemist, vault infiltrator.', 'They value secrecy, patience, and mastery of specialized subterranean knowledge. Dark Elves see the deep places of the world as both a refuge and a fortress, shaping their lives around what those environments demand. They thrive where others would falter, using an intimate understanding of their surroundings to control the terms of any encounter. Outsiders often mistake their reserve for hostility, but in truth, trust simply takes time to earn. To them, knowledge hoarded is power preserved, and power preserved is survival assured.', 'They see arcane resurgence as another layer in subterranean ecosystems—new glyphs etched in rock, unexpected reactions in deep waters.'),
  (24, 'race-69e384637891093aaf64dc238221f7397f0038b0c079b00c0ddff3c849406262', 'Moonshade Elf', 'Moonshade Elves are silver-blooded seers whose lives are shaped by the ebb and flow of lunar visions. Once, their guidance charted the safest threads of fate for leaders, merchants, and wanderers, weaving destinies with quiet precision. When the great divination currents waned, many withdrew into seclusion, entering trances to preserve ancient rites until omen-tides returned. Their waking years are spent listening for the faint ripple of tomorrow in the still waters of the present. Moonshade Elves carry themselves as if each movement and word might shift the balance of unseen threads. They are trained in decoding dreams, tracing symbolic echoes, and reading subtle cues in the world’s rhythm. Their calm is not detachment but deliberation—measuring each choice against futures only they can glimpse. They understand that prophecy is a current to navigate with care, lest their words steer events toward unintended shores. Their legacy is one of patience, empathy, and the belief that clarity is a gift worth guarding until the right moment.', 'Average Height: 5′4″–6′0″; Average Weight: 110–180 lbs; Proportions: slender, light-boned build; Skin Color: moonlit charcoal tones; Hair Color: spun-silver with fine, fiber-optic sheen; Eye Color: mercury-bright irises; Notable Features: fingers stained with silver ink from ritual scribing.', 'Move with a graceful, near-weightless gait and an attentive, measured poise. Garments favor pale silvers, deep charcoals, and rune-stitched accents, with thin veils or circlets inscribed with omen marks as common accessories. Presence is quiet yet focused, like one listening for distant tides before speaking.', '30–400', 30, 400, 'Medium', 2, 'Lunar Augury', 'Once per session, glimpse a near-future thread—grant +10 to the next Insight, Investigation, or Perception roll for self or an ally.', 'Vision backlash—take –10 on the user’s next Wisdom- or Intelligence-based roll.', 'Common; Lunarian Cant (dream-speech runes)', 'Dream-scribe Diplomat; Omen-Path Navigator; Argent Seer', 'Fantasy – Court seer guiding expedition routes. Sci-Fi – Probability analyst forecasting outcomes for interstellar negotiations. Post-Apocalyptic – Route-finder mapping safe passages through shifting hazards.', 'Moonshade Elves value clarity, balance, and mercy, believing that each decision shapes the threads of many possible futures. They practice discretion in counsel, offering guidance only when the moment is right, and strive for empathy in judG.O.Dent without neglecting accountability. Patience is seen as a strength, and they will often delay action until conditions align for the best outcome. Symbolism and subtle patterns hold deep meaning to them, influencing how they interpret events and choose their paths. They prefer cooperation over conflict, seeking solutions that preserve harmony, yet they remain prepared to act decisively when balance is threatened. To them, stability in the present is the foundation for a future worth building.', 'Treat magic as one of many forces that shape the world—powerful, unpredictable, and best approached with disciplined care regardless of its form or source.'),
  (25, 'race-81b1b8dd15dd1247936fff656b41575a5d2bd5c29fdbae0257d6f1e5c9a2d317', 'Satyr / Faun', 'Satyrs and Fauns are creatures of rhythm and resonance, living embodiments of music’s power to unite and inspire. Their lineage traces back to the forest revels of ancient times, where they served as keepers of joy, community, and the subtle magic that flows through song. Even in the modern era, they carry this role into festivals, rituals, and public gatherings, using their innate charisma to bind people together. The horns and cloven hooves of their form are less a mark of the wild than of a deep connection to the primal heartbeat of the world. Satyrs and Fauns treat every social gathering as a living composition, each voice and movement a note in a shared performance. Their talents are not limited to the stage—they are also healers of morale, able to lift spirits in dark times through the right melody or word. Outsiders often see them as frivolous or overly indulgent, but beneath their mirth lies a sharp awareness of human (and nonhuman) nature. They use this understanding to guide moods, mend rifts, and inspire courage when needed most. Their legacy is one of celebration as resistance—proving that joy and connection are as vital to survival as food and shelter.', 'Average Height: 5′2″–6′0″; Average Weight: 110–180 lbs; Proportions: graceful, balanced build; Skin Color: natural tones; Hair Color: varied; Eye Color: varied; Notable Features: cloven hooves, curling horns, bioluminescent markings responsive to sound.', 'Satyrs and Fauns wear clothing that allows freedom of movement, often with decorative elements that accentuate their natural features. They move with rhythmic ease, and their markings may subtly pulse in time with nearby music or ambient sound. Accessories often include musical instruments or items linked to performance.', '18-120', 18, 120, 'Medium', 3, 'Resonant Crescendo', 'Once per gaming session when performing or speaking, roll Charisma: Success: Echoes of their voice grant +10 to the party’s next Performance Arts, Persuasion, or Leadership roll.', 'Failure: Overreach the crescendo—impose –10 on their own next Performance Arts or Persuasion roll.', 'Common, Elven High-Cant, Bardic Cant', 'Festival Logistician; Mixology Maestro; Therapeutic Sound-Healer', 'Fantasy – Bardic envoy, ritual healer, festival organizer. Sci-Fi – Resonance therapist, cultural ambassador, sonic architect. Post-Apocalyptic – Traveling morale-keeper, broadcast DJ, survivor camp entertainer.', 'They value harmony through social connection, using music, dance, and celebration as bridges between people. Satyrs and Fauns see joy as a form of resilience, a way to strengthen bonds in times of both peace and hardship. They are quick to invite others into their revels, believing that shared experiences build lasting trust. While they can be lighthearted, they are not frivolous—beneath the laughter lies a keen sense of when to charm, when to comfort, and when to persuade. To them, community thrives best when the spirit is nourished alongside the body.', 'To Satyr/Fauns, magic is another chord in the grand symphony of existence. They eagerly incorporate arcane vibrations into new instruments and rituals.'),
  (26, 'race-e88559cc13f4588e472da7890fd09085b0f2e4fb20d7ffdb058866f4d7ba1dc9', 'Minotaur', 'Minotaurs are the navigators of the world’s complexities—born with an uncanny sense of direction and a patience forged in the winding turns of their ancestral labyrinths. Their heritage speaks of stone corridors and ritual paths, but in the modern era they stride just as confidently through the concrete jungles of sprawling cities. Minotaurs value discipline, structure, and the comfort of patterns, seeing each day as a series of routes to be mastered and improved. They are slow to trust but fiercely loyal to those who have walked beside them through life’s figurative and literal mazes. While their strength is formidable, they place equal pride in their ability to map, plan, and anticipate. Outsiders often mistake their methodical pace for stubbornness, but Minotaurs know that a wrong turn taken in haste can cost more than time—it can cost lives. They are often found in leadership roles within logistical hubs, ensuring that goods, people, and information move efficiently through complex networks. Chaos unsettles them, but also inspires them to impose order, finding pathways even in uncertainty. Their legacy is one of perseverance, structure, and guiding others safely to their goals.', 'Average Height: 6′2″–7′6″; Average Weight: 220–350 lbs; Proportions: broad-shouldered, massive build; Skin Color: natural tones with coarse hair coverage; Hair Color: dark, often short; Eye Color: brown, amber, or black; Notable Features: prominent horns, hooved feet.', 'Minotaurs tend to wear durable, functional clothing suited to work or travel, often reinforced at the shoulders and chest to accommodate their build. Their gait is steady and deliberate, and their equipment is arranged for balance and accessibility.', '18-150', 18, 150, 'Large', 2, 'Labyrinthine Resolve', 'Once per gaming session when lost or confronted with a complex layout, roll Wisdom: Success: Instinctively find the optimal path, granting +10 to the party’s next Navigation or Investigation roll.', 'Failure: Overthink the routes—impose –10 on their own next Navigation or Survival roll.', 'Common, Minotaur Tongue (labyrinth runes)', 'Freight-Hub Supervisor; Warehouse Flow Architect; Escape-Room Designer', 'Fantasy – City guard captain, royal maze-keeper, caravan route-master. Sci-Fi – Spaceport docking director, asteroid mining foreman, megastructure maintenance lead. Post-Apocalyptic – Wasteland pathfinder, fortified settlement overseer, underground safe-route broker.', 'They value patterns, order, and shared discipline, seeing structure as the path to strength. Minotaurs often organize their lives and communities with the same precision they apply to training or craftsmanship. They respect authority earned through competence and expect those in power to act for the collective good. While they can appear inflexible, this is usually a reflection of their belief that stability is worth defending. To them, the greatest threat is not open conflict but the slow erosion of unity from within.', 'They regard magic as another set of patterns to decode—arcane currents mapped like tunnels.'),
  (27, 'race-f74f0db5bf0b1909bd6e9659a721db5d855e693171ad3b0bb2676163522306bf', 'Dryad-Blooded', 'Dryad-Blooded are living connections between humanity and the green heart of the world. Born with plant-like features and a bond to the environment, they serve as both guardians and interpreters of nature’s quiet messages. Their skin patterns shift with air quality and humidity, serving as living barometers that read the health of the surrounding ecosystem. Communities rely on them to monitor environmental changes, from the subtle creep of urban smog to the renewal of seasonal blooms. While they can thrive in cities, Dryad-Blooded always seek to maintain a link to soil, sunlight, and growing things. They value cycles of renewal, seeing destruction not as an end but as an invitation for regrowth. Outsiders often find them serene, though this calm hides a fierce determination to protect the balance they sense in every breath of wind and drop of rain. They blend traditional botanical knowledge with modern tools, creating living infrastructure that benefits both people and nature. Their legacy is one of stewardship, resilience, and the belief that every community can learn to breathe in harmony with its surroundings.', 'Average Height: 5′0″–6′2″; Average Weight: 100–180 lbs; Proportions: slender to medium build; Skin Color: green or amber with branching vein-like patterns; Hair Color: interwoven with moss or lichen; Eye Color: green, amber, or brown; Notable Features: bark-like nails.', 'Dryad-Blooded attire often incorporates natural fibers, plant motifs, or living adornments. They carry themselves with a calm, grounded demeanor, and their skin patterns shift subtly with environmental changes. Accessories may include tools for tending plants or monitoring environmental conditions.', '20-300', 20, 300, 'Medium', 2, 'Living Barometer', 'Skin patterns glow or wither in precise hues, granting +10 to the next Survival or Investigation roll tied to environmental analysis.', 'They misinterpret the signals, imposing –10 on their next related roll.', 'Common, Sylvan, plus one local dialect', 'City Air-Sensor Tech; Botanical Perfumer; Vertical-Farm Operator', 'Fantasy – Grove warden, herbalist healer, weatherwise scout. Sci-Fi – Bioengineered habitat technician, terraforming botanist, environmental monitor. Post-Apocalyptic – Greenhouse guardian, water-purification steward, urban reclamation specialist.', 'They value balance, cyclical renewal, and shared stewardship of the living world. Dryad-Blooded see themselves as both guardians and participants in the natural order, working to maintain harmony between growth and decay. They are deeply patient, often thinking in seasons rather than days, and adapt their efforts to the slow rhythms of change. While they can be fiercely protective of the places they call home, they are equally willing to help restore damaged lands elsewhere. To them, every choice should serve the long arc of life’s renewal.', 'They welcome magic as a revival of primal harmony—seeking symbiosis with awakened ley lines.'),
  (28, 'race-2d1d83250720679fb609f8fc68ebfc39b359541dcb117a606ff55958280ad3bb', 'Changeling', 'Changelings are shapeshifters caught between countless identities, able to adapt their appearance with uncanny precision. Their origins lie in the veiled arts of illusion, but centuries of living among other peoples have turned their gift into a survival tool as much as an art form. A Changeling’s true face is often unknown even to their closest companions, hidden beneath a lifetime of crafted personas. They thrive in roles that require adaptability, deception, or seamless blending into varied communities. This constant shifting fosters an acute awareness of social dynamics, allowing them to navigate complex situations with ease. Yet behind every mask lies a question of self—whether their true identity is a single, hidden truth or a collage of every face they have worn. Outsiders may admire their versatility or mistrust their shifting nature, but few can deny the value of their talents in diplomacy, espionage, or performance. Changelings themselves see their power as both liberation and burden—freedom to become anyone, but at the cost of rarely being truly known. Their legacy is one of adaptability, concealment, and the art of becoming exactly what a situation demands.', 'Average Height: 4′8″–6′0″; Average Weight: 90–180 lbs; Proportions: variable within range; Skin Color: pale; Hair Color: variable; Eye Color: opalescent, reflecting ambient colors; Notable Features: androgynous facial structure, faint scar-patterns.', 'Changelings present in shifting forms, altering features, build, and mannerisms to suit their surroundings. Their attire changes as readily as their faces, selected to blend seamlessly into a chosen role or environment. Movements and expressions are deliberate, calibrated to reinforce the identity they project.', '18-120', 18, 120, 'Medium', 2, 'Glamour Veil', 'Gain +10 to Stealth or Deception for 1 minute or 1 combat step.', 'The illusion flickers, imposing –10 on their next Stealth or Deception roll.', 'Common, Elven High-Cant', 'Street Actor; Infiltration Decoy; Fashion Double', 'Fantasy – Court spy, royal actor, magical body double. Sci-Fi – Corporate identity thief, holo-performer, undercover agent. Post-Apocalyptic – Safehouse impersonator, disguise merchant, faction infiltrator.', 'They value adaptability, discretion, and the freedom of self-reinvention. Changelings see identity as a tool rather than a fixed truth, shifting appearance or demeanor as needed to navigate the worlds they move through. This flexibility makes them skilled negotiators, infiltrators, or mediators, but it can also leave others unsure of where their loyalties lie. They tend to measure trust in shared actions rather than words, and they rarely reveal their full selves to anyone. To them, survival and freedom are often two sides of the same mask.', 'They view the awakening Guardian of Illusion as both a promise and a threat—an end to their anonymity but a path to true self-expression.'),
  (29, 'race-6ad7a9fc97f8d9cd83911ba2f5f3528a344fec36092359df7d5d265125bab8d3', 'Smallfolk', 'Smallfolk are proof that stature says nothing about impact. Standing knee-high to most, they’ve cultivated a legacy rooted in cooperation, resilience, and harmony with the land. Their settlements are models of shared labor and collective reward, where everyone from brewer to weaver has a voice in the harvest feast. Generations of working the soil and tending livestock have honed their instincts for sustainable living, and even in urban settings they maintain rooftop gardens or small green spaces. While they favor a slower pace of life, they are far from idle—crafting exceptional goods, brewing spirits that rival any major distillery, and practicing trades that keep communities thriving. Outsiders often mistake their friendliness for naivety, but beneath their warmth lies an unyielding will to protect their homes. Stories of Smallfolk ingenuity are common: barricading a flood with barrels in minutes, outmaneuvering raiders with hidden footpaths, or turning a failing crop into a thriving co-op venture. They measure wealth not in coin but in the health of their fields, the fullness of their stores, and the laughter of their kin. Their legacy is one of stewardship, quiet innovation, and proving that even the smallest people can cultivate great change.', 'Average Height: 2′6″–3′6″; Average Weight: 40–60 lbs; Proportions: compact, sturdy build; Skin Color: light to medium, often weather-hardened; Hair Color: natural earthy tones; Eye Color: bright, varied; Notable Features: calloused hands.', 'Smallfolk dress in practical garments suited to manual work or tending land, often with visible signs of wear from daily labor. Their posture is open and inviting, and they move with an easy familiarity in rural or garden-like settings. Tools and personal items are often hand-crafted or well-maintained.', '20-150', 20, 150, 'Small', 1, 'Rootstep Resilience', 'They and allies within 5 ft gain +10 to the next Survival or Constitution roll resisting hardship.', 'They misjudge the conditions, imposing –10 on their own next roll of that type.', 'Common plus one regional dialect or folk-tongue.', 'Micro-Brew Master; Hydroponic Caretaker; Youth-Counsellor', 'Fantasy – Hearth witch, village brewer, herbwise healer. Sci-Fi – Hydroponics technician, asteroid biodome caretaker, communal quartermaster. Post-Apocalyptic – Seed archivist, rooftop farmer, resilient enclave elder.', 'They prize reciprocity, sustainable methods, and the quiet pulse of rural life. Smallfolk tend to live in close-knit communities where everyone’s efforts contribute to the well-being of the whole. They view prosperity not in terms of personal wealth, but in the shared health and happiness of the group. Change comes slowly, shaped by consensus rather than impulse, and traditions are valued as anchors in uncertain times. While they are hospitable to outsiders, trust is earned through deeds, not words, and loyalty is returned in kind.', 'Magic is like rain—nourishing when gentle, devastating when unleashed.'),
  (30, 'race-a2255caec644ee9f674224ee9acb5191772070aaf80399095d260b8ad755caf0', 'Mer-Folk', 'Mer-Folk are amphibious stewards of both land and sea, bridging two worlds with grace and adaptability. Their history is entwined with the ebb and flow of tides, guiding ships through treacherous shallows and guarding ancient ruins beneath the waves. They are as comfortable navigating coral labyrinths as they are walking market docks, often acting as intermediaries between surface traders and deepwater clans. Community is central to Mer-Folk culture, with responsibilities shared in maintaining both aquatic and coastal ecosystems. They are adept at reading currents, tracking marine life, and predicting weather shifts long before the sky changes. Outsiders often romanticize them as oceanic mystics, but Mer-Folk see themselves more as practical guardians, ensuring balance in the environments they inhabit. Their skills make them invaluable in salvage operations, marine research, and deep-sea exploration. While their adaptability is impressive, extended separation from water can tax their strength, making coastal access vital. Their legacy is one of cooperation, environmental stewardship, and seamless navigation between realms.', 'Average Height: 5′0″–6′2″ (tail length in hybrid form adds overall length); Average Weight: 100–180 lbs; Proportions: slender, streamlined build; Skin Color: scale-flecked in shades of blue, green, or pearl; Hair Color: varied natural tones; Eye Color: blue, green, or grey; Notable Features: webbed fingers.', 'Mer-Folk favor streamlined clothing and gear for aquatic movement, often decorated with shells, coral accents, or water-resistant materials. Their posture and movements are fluid, with a practiced ease in both swimming and walking. Equipment is designed for quick transition between land and water use.', '18-130', 18, 130, 'Medium', 2, 'Current’s Embrace', 'Gain +10 to the next Swimming, Survival, or Navigation roll in aquatic conditions.', 'Caught in a reverse eddy—suffer –10 on their next related roll.', 'Common, Aquan (underwater dialect)', 'Harbor Pilot; Marine-Cleanup Diver; Aquarium Presenter', 'Fantasy – River guardian, sea temple acolyte, pearl diver. Sci-Fi – Deep-space aquatic habitat technician, exoplanet ocean explorer, amphibious rescue diver. Post-Apocalyptic – Floodplain scout, tidal salvage operator, coastal settlement defender.', 'They value cooperation, respect for natural rhythms, and trade that sustains both people and environment. Mer-Folk see the currents of the world—whether in water, wind, or politics—as forces to work with, not against. They are adept navigators of both literal and social tides, using patience and timing to achieve their aims. While they can be cautious with strangers, fair dealings and mutual respect can open lasting channels of alliance. To them, survival depends on balance, and balance depends on honoring the flow that connects all things.', 'They see magic as another tide—ebb and flow of unseen forces.'),
  (31, 'race-d7b45c44f4e11b8e535f0628a293ed3d79bb5a69315519f0641006bcaec3cfb2', 'Centaur', 'Centaurs are tireless travelers, their lives bound to the open road and the unbroken horizon. With the lower body of a powerful horse and the upper body of a human, they embody speed, endurance, and unshakable purpose. Their history is filled with tales of great migrations, where entire clans would journey for weeks without stopping, guided by the stars and an intimate knowledge of the land. They are natural navigators, able to recall trails and waypoints after a single pass, and they take pride in keeping the routes they travel safe for others. Centaurs value punctuality, seeing it as a form of respect for those who await their arrival. Their settlements are often temporary encampments at key crossroads, serving as waystations for travelers and merchants. They are fiercely protective of these routes, viewing themselves as guardians of the flow of goods, news, and people. While their strength and stamina are their most obvious assets, Centaurs also possess keen senses and a strong communal ethic, working together to maintain safe passage for all. Outsiders often admire their discipline and dedication, though some see them as overly rigid. Their legacy is one of service, movement, and the unyielding pursuit of the next destination.', 'Average Height: 5′6″–6′6″ (human torso to withers); Average Weight: 400–600 lbs; Proportions: human upper body with equine lower body; Skin Color: natural human tones; Hair Color: varied; Coat Color: solid or patterned natural horse shades; Eye Color: human or equine tones; Notable Features: hooved feet, equine tail.', 'Centaurs wear fitted upper garments for protection and utility, leaving the lower body unarmored or lightly protected for mobility. Movement is powerful and steady, with a balanced gait suited for long distances. Gear is often carried in saddle-like packs or harnesses.', '15-110', 15, 110, 'Large', 1, 'Stamina Surge', 'Sustain supreme endurance, gaining +10 to the next Athletics, Survival, or Strength-based roll.', 'Overextend, suffering –10 on their next Strength or Constitution-based roll.', 'Common', 'Emergency Blood-Run Courier; Mounted Park Ranger; Endurance Sport Promoter', 'Fantasy – King’s messenger, frontier scout, wild plains guardian. Sci-Fi – Gravity track courier, alien terrain ranger, megacity patrol mount. Post-Apocalyptic – Nomadic supply runner, wasteland guide, mobile settlement scout.', 'They value punctuality, mutual aid, and respect for the natural waypoints of life’s journey. Centaurs see travel not just as movement, but as a cycle of departures and returns, with each stage carrying its own responsibilities. They often act as guides, mediators, or scouts, using their speed and endurance in service to the communities they support. Tradition shapes their routes and gatherings, yet they are not bound so tightly to it that they cannot adapt when the terrain—or the times—demand it. To them, every destination is a milestone, and every milestone is a chance to reaffirm bonds.', 'Centaurs see magic as an elemental current—akin to wind in hair and thunder in hooves.'),
  (32, 'race-1168316deaa840e35445d5af8220668c6110557e0c03b2e15d35cea248e0b924', 'Shift-Folk (Lupine)', 'From the first whispered campfires to the crowded skylines of the present age, the Lupine Shift-Folk have walked between two worlds—part human, part something older and wilder. Their ancestors roamed open plains and deep forests, running in tight-knit packs whose survival depended on shared vigilance and mutual trust. In times before recorded history, their keen senses and endurance made them natural hunters, scouts, and guardians, tracking prey or enemies for days without rest. Even in modern societies, this heritage shows: Lupines pace the edges of cities, eyes scanning for trouble others miss, ears tuned to the subtle rhythms of life. Loyalty is not an abstract virtue for them but a binding force—packs, whether formed by blood or choice, are sacred bonds never broken lightly. They tend to speak plainly and act decisively, preferring direct action over tangled politics, though they will guard the vulnerable with unshakable resolve. Outsiders often see them as fierce or aloof, yet those welcomed into their circle find a depth of warmth and protectiveness that rivals any hearth or home. In urban settings, Lupines gravitate toward roles that echo their old trails: search-and-rescue teams, night patrols, and wilderness guides, where their instincts and stamina shine. Rural or frontier Lupines still keep the old ways alive, teaching pups the language of wind and soil, the meaning of moon phases, and the importance of the silent signal passed from one runner to another. Across all worlds and eras, the Lupine Shift-Folk carry the tension of two selves—the steady heartbeat of the human and the wild, unshackled pulse of the wolf—awaiting the day the Guardian of Transformation calls them to run freely under the open sky once more.', 'Unshifted Form: Height: 5′6″–6′2″; Weight: 140–200 lbs; lean musculature; Hair: slate-gray or dark with silver streaks; Eye Color: pale yellow, intensifies in low light. Animal Form: Height (at shoulder): 30–36 in; Length: 5′0″–6′0″ nose-to-tail; Weight: 80–120 lbs; thick fur, strong shoulders. Hybrid Form: Height: 6′0″–6′8″; Weight: 190–250 lbs; digitigrade legs, partial muzzle, fur on limbs/torso, claws, fangs. Empowered Hybrid Form: Height: 6′4″–7′0″; Weight: 220–280 lbs; increased muscle mass, thicker fur, glowing eyes.', 'Lupine Shift-Folk carry themselves with alert posture, scanning their surroundings and moving with a balanced, ready gait. Their clothing and gear favor mobility and durability, often suited for outdoor or patrol work. In any form, movements are direct and efficient, with a tendency toward protective positioning near allies.', '16-90', 16, 90, 'Medium', 2, 'Moonlight Resilience', 'Gain +10 to the next Survival or Perception roll under moonlight or dim conditions.', 'Misjudge the shadows—incur –10 on their next Survival or Perception roll.', 'Common', 'SAR K-9 Partner; Wilderness Ranger; Distance Runner', 'Fantasy – Wolf-cavalry scout, royal courier of the wild roads. Sci-Fi – Terraforming frontier tracker, security recon operative on alien worlds. Post-Apocalyptic – Wasteland forager, night-run supply escort.', 'They prize loyalty, shared hardship, and the clarity of the hunt. Open spaces feel like home, while crowded courts feel like cages. To them, the pack is identity, and every member’s survival is a shared responsibility. Lupine Shift-Folk are quick to defend their own but deliberate in accepting outsiders, weighing not just strength but trustworthiness. They believe that leadership is earned through action, and that no one is above the needs of the pack as a whole.', 'They sense the Guardian’s stir in bone and sinew—yearning for their final form to awaken, when man and wolf meld without restraint.'),
  (33, 'race-86ae8a23bb3637408e07a7af8fbc952f405db7c4d5285299dd8d9ad45d33a46f', 'Shift-Folk (Feline)', 'From the tangled canopies of primeval jungles to the sprawling skylines of megacities, the Feline Shift-Folk have always been creatures of balance—masters of stealth and grace who walk the line between predator and observer. Their ancestors stalked prey from high branches or shadowed cliffs, leaping with precision when the moment was right. In ancient times, they were revered as both protectors of sacred spaces and bringers of sudden justice, their silent approach striking fear into those who broke oaths. Felines move through life with measured patience, never expending more energy than needed, yet striking decisively when opportunity presents itself. Their independence is a point of pride, but within trusted circles they demonstrate remarkable coordination, flowing together like parts of a single body in motion. Urban Felines adapt rooftops and scaffolded heights into their hunting grounds, scaling neon towers with the same ease their ancestors navigated forest canopies. Rural and frontier kin remain close to nature’s edges, teaching younger generations the old arts of stalking, tracking, and silent observation. Outsiders often misread their quiet watchfulness as disinterest, not realizing that every flick of the eye and tilt of the ear is calculated awareness. In any society, they are the unseen thread between events—the messenger who arrives before trouble, the sentinel who spots the shift in the wind, the presence you didn’t know was there until they chose to be seen. Across all worlds and eras, the Feline Shift-Folk embody the discipline of stillness and the swiftness of precision, awaiting the Guardian of Transformation’s call to unleash their full potential.', 'Unshifted Form: Height: 5′4″–6′0″; Weight: 130–190 lbs; lean, flexible musculature; Hair: varied, often tied/cropped; Eyes: reflective in low light. Animal Form: Height (at shoulder): 26–32 in; Length: 4′6″–5′6″ nose-to-tail; Weight: 80–140 lbs; patterned or solid fur, retractable claws. Hybrid Form: Height: 5′8″–6′4″; Weight: 160–220 lbs; digitigrade legs, partial muzzle, fur on forearms/shins/shoulders, claws, tail for balance. Empowered Hybrid Form: Height: 6′0″–6′6″; Weight: 180–240 lbs; thicker claws, enhanced musculature.', 'Feline Shift-Folk move with controlled precision and economy of motion. Attire is fitted for climbing and stealth, minimizing loose fabric. In animal or hybrid form, they favor elevated or concealed vantage points, using fluid transitions between stillness and sudden movement.', '18-120', 18, 120, 'Medium', 2, 'Night Prowler’s Instinct', 'Gain +10 to the party’s next Wisdom-based skill check (Perception, Investigation, or Animal Handling) in low-light conditions.', 'Suffer –10 on their own next Wisdom-based roll.', 'Common', 'Facade Climber; Stealth-Testing Auditor; Express Courier', 'Fantasy – Royal assassin’s scout, high-canopy archer. Sci-Fi – Zero-g infiltration operative, vertical salvage runner. Post-Apocalyptic – Ruined city rooftop courier, silent sniper in overgrown zones.', 'They prize independence, precision, and quiet efficiency. Feline Shift-Folk prefer to act alone when possible, but within trusted circles they display perfect timing and seamless cooperation. Patience is one of their greatest strengths, allowing them to watch and wait until the exact moment to strike or withdraw. They value skill over brute force, seeing the art of movement and subtlety as marks of mastery. To them, the greatest victories are those won without wasted effort.', 'Magic’s return is a new realm to prowl—its shadows become calculated advantage, its mysteries new hunting grounds.'),
  (34, 'race-581871a6819ae31cff0b58ba6e8708b42c427494545fa6b4518e0dcace44c707', 'Shift-Folk (Ursine)', 'The Ursine Shift-Folk are living monuments to endurance—beings who have weathered the grinding winters of mountain passes, the slow burn of desert heat, and the crushing labor of ages. Their history is a story of steadfast service: hauling siege engines across ice fields, holding bridgeworks against storms, and digging lifelines through bedrock when lesser bodies faltered. Patience is their greatest weapon; they can hold a defensive line long after an enemy’s will to fight has frayed. In peaceful times, Ursines turn that same patience toward construction, agriculture, and guardianship, building things meant to last centuries. They speak little when words will not improve a situation, but their silence is rarely empty—it is measured thought before decisive action. Among their own, they share a humor as deep and slow as a thawing river, and their festivals are as much about honoring shared labor as they are about revelry. Outsiders often mistake their deliberate pace for slowness, not realizing that an Ursine never rushes toward a task they do not intend to finish. Their loyalty, once earned, is granite—immovable and enduring through all hardship. Though they can strike with the force of a falling tree, they prefer to be the unshakable wall others rally behind. Across centuries and settings, the Ursine Shift-Folk embody the power of slow, steady strength—awaiting the Guardian of Transformation’s call to channel that strength into forms both fearsome and awe-inspiring.', 'Unshifted Form: Height: 5′0″–5′6″; Weight: 160–220 lbs; wide, solid frame; Hair: thick, coarse, dark shades. Animal Form: Height (at shoulder): 3′0″–4′6″; Length: 6′0″–8′0″ nose-to-tail; Weight: 300–700 lbs; thick insulating fur. Hybrid Form: Height: 6′6″–7′6″; Weight: 300–450 lbs; digitigrade legs, elongated arms with claws, partial fur, pronounced muzzle. Empowered Hybrid Form: Height: 7′0″–8′0″; Weight: 350–500 lbs; denser fur, longer claws, increased reach.', 'Ursine Shift-Folk maintain a steady, deliberate bearing. Clothing is practical and reinforced, allowing for heavy lifting or sustained outdoor work. Movements are slow but purposeful, shifting to explosive force when required. In hybrid or animal form, they exhibit grounded stances and wide, stabilizing movements.', '30-350', 30, 350, 'Large', 2, 'Torpor Stamina', 'Gain +10 to the next Survival or Mental Fortitude roll as their torpor-driven stamina prevails.', 'Limbs stiffen—suffer –10 to the next Survival or Mental Fortitude roll.', 'Common', 'Deep-Mine Drilling Specialist; Freight Coupling Crew Lead; Heavy Equipment Repair Technician', 'Fantasy – Siege breaker, fortress gatewarden, stone quarry master. Sci-Fi – Bulk freighter dock foreman, hazardous-environment power suit operator. Post-Apocalyptic – Settlement wall-builder, mutant-zone freight escort, bunker door engineer.', 'They value endurance, reliability, and the long view. Ursine Shift-Folk are slow to commit but resolute once a path is chosen, favoring solutions that will stand the test of time. They see strength as a tool for protection before conquest, using it to shield what matters most. While they may seem slow to react, their measured pace is deliberate—ensuring that when they move, it is with purpose and weight. To them, the fiercest power is the kind that does not need to be proven daily.', 'Magic’s return is a slow-burn forge—tempering already mighty bodies into living siege engines, but approached with the same caution as a new and untested tool.'),
  (35, 'race-f4beb1015cabb6d33eff1ff64fe018729c43d699c083a9c425793cd326f0e328', 'Shift-Folk (Avian)', 'The Avian Shift-Folk are born with their eyes on the horizon and their thoughts shaped by the open sky. Throughout history, they have been the scouts, couriers, and lookouts who bridged vast distances in hours instead of days, their elevated perspective changing the course of battles, trade, and exploration. Even unshifted, they read the wind and sky as easily as most read the ground beneath their feet. Legends speak of Avian sentinels who could spot an ambush from miles away, or deliver messages faster than any rider or signal flare. Their cultures are built on principles of clarity, foresight, and freedom of movement—where being grounded too long is as unnatural as being caged. They measure wealth in vantage points and wind-mapped routes, treating each current as both resource and territory. Despite their mobility, they are fiercely loyal to their home roosts, returning seasonally to share news, trade goods, and ensure the safety of their kin. In peacetime, they serve as aerial cartographers, weather predictors, and high-rise engineers, always seeking the next unexplored path through the air. While they are capable of decisive action, they prefer to plan from a position of height, reading situations from above before committing to a course. To the Avian Shift-Folk, the Guardian of Transformation is not simply a herald of change—it is the promise of reclaiming the sky in its fullest, most powerful form.', 'Unshifted Form: Height: 5′4″–6′0″; Weight: 120–170 lbs; agile build, elongated limbs, aerodynamic bone structure; faint shoulder ridges. Animal Form: Height (standing): 18–24 in; Wingspan: 5′6″–7′6″; Weight: 6–18 lbs; strong wings, sharp talons. Hybrid Form: Height: 5′8″–6′4″; Weight: 140–190 lbs; humanoid with feathered wings, talon nails, hollow bones. Empowered Hybrid Form: Height: 6′0″–6′6″; Weight: 150–200 lbs; broader wingspan (8′0″–10′0″), enhanced musculature.', 'Avian Shift-Folk favor lightweight clothing and harnesses for gear, ensuring freedom of wing movement. Posture is upright with subtle forward lean, and gaze often scans elevated angles. In flight-capable forms, movements are smooth and wind-aware, with calculated landings and takeoffs.', '18-300', 18, 300, 'Medium', 2, 'High-Altitude Poise', 'Gain +10 to the next Acrobatics or Perception roll at elevation.', 'Thin air disorients—incur –10 on the next Acrobatics or Perception roll.', 'Common', 'Telecom Tower Tech; Aerial Photographer; High-Rise Window Crew', 'Fantasy – Royal messenger, aerial scout for border patrols, griffon-stable coordinator. Sci-Fi – Zero-G navigation specialist, atmospheric skydock inspector, drone-based map surveyor. Post-Apocalyptic – Settlement lookout, wind-turbine mechanic, skybridge courier.', 'They value perspective, mobility, and the ability to stay ahead of unfolding events. Avian Shift-Folk often weigh choices from a broad view, preferring to see how all the pieces fit before acting. Swift in both thought and movement, they adapt quickly when conditions change, avoiding traps—literal or metaphorical—through careful observation. Their freedom is fiercely guarded, but they will commit to a cause if it aligns with their sense of vision. To them, the highest perch is not for dominance, but for clarity.', 'Magic is a new current in the skies—unseen and unpredictable, yet chartable by those with the vision and skill to ride it.'),
  (36, 'race-920b9e20653fa5304e17482c60d20c8b0581543be6e3baf7801e4ae30fb7ab7d', 'Shift-Folk (Bovine)', 'The Bovine Shift-Folk carry a legacy of quiet strength, enduring labor, and grounded wisdom that has supported civilizations for centuries. Known as the living engines of harvest and haul, they have historically been the ones who could work the fields from dawn to dusk, clear land for settlement, or carry burdens that would break lesser backs. Even unshifted, their patience and fortitude set them apart—valuing deliberate progress over hasty action. In their ancestral stories, heroes are rarely the ones who rush into battle, but rather those who hold the line, withstand the storm, and see the work through until the last stone is placed. They are deeply connected to the cycles of the land, reading seasonal changes in the taste of forage or the smell of soil. Communities built by Bovine Shift-Folk tend to be stable and self-sustaining, with an emphasis on food security, shelter, and shared labor. They are skilled at navigating harsh climates and making use of scarce resources, traits that have allowed them to thrive even in environments others abandoned as inhospitable. When the Guardian of Transformation stirs, it awakens the full measure of their latent might, granting them forms capable of both immense physical force and steadfast defense. For them, transformation is not about speed or grace—it is about becoming an unmovable wall or an unstoppable force when the moment demands it.', 'Unshifted Form: Height: 5′8″–6′4″; Weight: 180–260 lbs; broad, stocky build; Skin: warm earthy tones; Eyes: brown or amber. Animal Form: Height (at shoulder): 4′6″–5′6″; Length: 6′0″–8′0″ nose-to-tail; Weight: 1,200–2,000 lbs; sweeping horns, sturdy stance. Hybrid Form: Height: 6′6″–7′4″; Weight: 300–450 lbs; humanoid-bovine with horns, thick musculature. Empowered Hybrid Form: Height: 6′10″–7′8″; Weight: 350–500 lbs; reinforced horns, denser muscle, increased lung capacity.', 'Bovine Shift-Folk stand and move with measured stability, often grounding themselves before action. Clothing is durable and reinforced at stress points. In hybrid or animal forms, their stance widens for balance, and they utilize deliberate, powerful motions.', '18-130', 18, 130, 'Medium', 2, 'Stomach of Steel', 'Gain +10 to the next Medicine or Survival roll dealing with poisons or harsh environments.', 'Misjudge the meal—suffer –10 on next Medicine or Survival roll.', 'Common', 'Industrial Compost Lead; Freight Stevedore; Rooftop Greenhouse Caretaker', 'Fantasy – Siege engine loader, village granary guardian, caravan beastmaster. Sci-Fi – Terraforming colony labor lead, freight elevator mechanic, biodome agricultural foreman. Post-Apocalyptic – Salvage hauler, mutant pasture herder, poison-soil reclamation specialist.', 'They value persistence, mutual aid, and careful preparation. Quick solutions are rare among Bovine Shift-Folk, but when they commit to a task, it is done thoroughly and without hesitation. They see strength as a communal resource, best used in service of shared goals. Change comes slowly to them, not out of resistance, but from a belief that stability must be built to last. To them, progress without a strong foundation is no progress at all.', 'Magic is seen as a kind of enchanted fertilizer—beneficial if balanced, destructive if applied carelessly. They prefer to test it in controlled conditions before trusting it in the open field.'),
  (37, 'race-67ef3794c4b6a88c5a546af065c0b9c231eaceda730d3bec0530f9fefbe831ac', 'Shift-Folk (Musteline)', 'Descended from the cunning and resourceful mustelids, these shapeshifters embody a blend of relentless curiosity and aquatic grace. In their unshifted form, they are indistinguishable from other humanoid races save for their subtly webbed fingers, sleek musculature, and eyes that seem to catch light like polished stones. Their communities thrive where land and water meet—tidal estuaries, riverbanks, or bustling canal towns—making a living through salvage, watercraft maintenance, and intricate repair work. Generations of working in submerged environments have honed both their problem-solving skills and their ability to adapt fluidly to changing circumstances. In social matters, Musteline folk favor cooperation tempered with sly wit, valuing those who can read the currents of conversation as well as the tides. Stories and traditions often revolve around the “flow,” a philosophy that champions adaptability and timing over brute force. When danger threatens, their transformations awaken in stages, each bringing them closer to the agile and powerful forms of their animal kin. This connection to water, craft, and calculated action makes them valued allies in trade, exploration, and conflict alike. Yet, they are not without pride—undermining one of their own’s competence can stir a deep, cold grudge. In any genre, they are as comfortable piloting a skiff through flooded ruins as they are in the depths of alien oceans.', 'Unshifted Form: Height: 5′2″–6′0″; Weight: 130–190 lbs; lean hydrodynamic build; slightly webbed fingers; skin: sun-browned tan to cool gray; hair: short/dense, shades of brown/black/gray; eyes: deep brown to glacial blue. Animal Form: Length: 2′0″–4′0″ nose-to-tail; Weight: 15–40 lbs; streamlined musteline body (otter, badger, or marten); short dense fur; muscular tail; partially webbed feet. Hybrid Form: Height: 5′4″–6′2″; Weight: 150–210 lbs; elongated torso; partial fur coverage; functional tail; claw-tipped fingers. Empowered Hybrid Form: Height: 5′6″–6′4″; Weight: 170–230 lbs; increased musculature; fully webbed hands/feet; heavy tail.', 'Musteline Shift-Folk move with a fluid, rolling gait and tend to stand with a subtle forward lean as if poised to dive. Clothing is streamlined for minimal drag and ease of movement in water. In animal or hybrid forms, their movements are quick, twisting, and efficient, optimized for tight spaces and sudden shifts in direction.', '12-60', 12, 60, 'Medium', 2, 'Waterborne Adaptation', 'Gain +10 to the next Survival or Perception roll in aquatic or damp environments.', 'Water masks senses—incur –10 on next related roll.', 'Common', 'Salvage Diver; Canal Lock Engineer; Pipe-Inspection Technologist', 'Fantasy: A river-guard scout who patrols trade routes, diving to clear debris from magical watergates. Sci-Fi: A hydro-salvage engineer aboard an oceanic research station on a water-world. Post-Apocalyptic/Modern: A survivor in a flooded city, navigating submerged skyscrapers to recover lost technology.', 'Adaptable and inventive, they value timing, resourcefulness, and cooperative problem-solving. Musteline Shift-Folk excel at navigating tight situations—whether those be physical spaces or social entanglements—by finding clever angles others overlook. They are unafraid to shift tactics midstream, seeing flexibility as a strength rather than a compromise. While they often work well in groups, they maintain a streak of independence that keeps them from relying too heavily on others. To them, survival is a mix of agility, wit, and knowing when to act.', 'Magic is viewed as another tool in the kit—respected for its practical applications but rarely romanticized.'),
  (38, 'race-53334549e6dcc46c9c0067cc637b775c2ef6a63d086e12e6507e15d16f3daee0', 'Shift-Folk (Murine)', 'Descended from nimble and quick-witted mouse-kind, these shapeshifters thrive in the hidden arteries of cities and starships alike. In their unshifted form, they blend easily into smallfolk communities, their stature and unassuming demeanor making them ideal for unnoticed movement. Murine folk have a natural affinity for navigating tight and complex spaces, from air vents and maintenance shafts to cramped cargo holds and machine bays. Generations spent in such environments have bred a culture of meticulous precision, patience, and quiet efficiency. They excel in mechanical diagnostics, delicate repairs, and systems monitoring, often forming the invisible backbone of infrastructure. Socially, they value communal trust, relying on a web of relationships where each member’s skills are recognized and appreciated. While soft-spoken by nature, they are fiercely loyal and will defend their communities with cunning and speed when threatened. Transformation unlocks their heritage in stages, bringing sharper senses, lightning reflexes, and unparalleled agility in confined environments. In any genre, they slip unseen through the world’s unnoticed spaces, solving problems before others even know they exist.', 'Unshifted Form: Height: 3′0″–4′0″; Weight: 45–80 lbs; slim build; short fur-like hair (gray, brown, cream); whisker-like facial hair; eyes: bright black or amber. Animal Form: Length: 6–12 in (body) + 6–10 in tail; Weight: 1–2 lbs; fine fur; long tail; sharp incisors. Hybrid Form: Height: 3′0″–4′2″; Weight: 50–85 lbs; mouse-like ears; whiskers; light fur; slender tail. Empowered Hybrid Form: Height: 3′2″–4′4″; Weight: 55–90 lbs; elongated limbs; refined tactile senses.', 'Murine Shift-Folk carry themselves with quick, alert motions, often scanning their surroundings with subtle head tilts. Attire is fitted for movement through tight spaces and for carrying tools in easy reach. In hybrid or animal forms, their movements are rapid, precise, and low to the ground, prioritizing stealth and access to narrow passages.', '8-100', 8, 100, 'Small', 2, 'Tightspace Niche', 'Gain +10 to the next Engineering or Investigation roll undertaken in tight or enclosed environments.', 'Misjudge a crawl-route—incur –10 on the next related roll.', 'Common', 'HVAC Crawl Technician; Vending-Machine Service; Automation QA', 'Fantasy: A guild infiltrator who maintains hidden passages beneath a castle, ensuring secret routes remain functional. Sci-Fi: A zero-G systems specialist who maintains and repairs life-support conduits on a massive space station. Post-Apocalyptic/Modern: A scavenger navigating collapsed tunnels and ventilation shafts to retrieve vital components from sealed zones.', 'Quiet, precise, and community-focused, they prefer preparation over confrontation. Murine Shift-Folk excel at working in coordinated groups where every role is clearly understood and valued. Their survival instinct is sharp, but it is tempered by a strong sense of duty to their own. While they may avoid open conflict, they are quick to rally when the safety of their group is at stake. To them, the smallest efforts, when multiplied across many hands, can achieve the greatest results.', 'Magic is regarded as another current flowing unseen through the world’s smallest conduits—respected for its utility, not spectacle.'),
  (39, 'race-9716bbc238db8b06b16369e79bc86e044555b74cdb7b58e37a544a787932d43f', 'Shift-Folk (Vulpine)', 'Descended from the keen-eyed and quick-witted fox, these shapeshifters carry an air of restless curiosity and calculated charm. In their unshifted form, they appear as sleek, sharp-featured humanoids whose subtle grace draws the eye without shouting for attention. Vulpine folk thrive where information flows thick and fast—urban sprawl, sprawling markets, neon-lit data hubs—trading in secrets, patterns, and the art of the well-timed question. They are social engineers and natural observers, seeing connections others miss and exploiting opportunities before they vanish. Their cultures often revolve around the concept of “the thread”—the belief that every mystery, no matter how tangled, can be traced to its root if one is clever enough to follow it. Storytelling, rumor-weaving, and subtle games of misdirection are as much survival tools as they are pastimes. Among themselves, they respect those who can navigate the web of truth and lies without becoming trapped in it. In dangerous situations, their instinct is not to meet force with force, but to manipulate the terrain—social, physical, or digital—until the advantage is theirs. Transformation unlocks latent predator instincts and precision agility, enabling them to pursue or evade with uncanny timing. Whether stalking corporate intrigue in a high-rise server farm, infiltrating the hidden tunnels beneath a fortified palace, or piecing together the truth behind a whispered apocalypse, the Vulpine are always hunting the next answer.', 'Unshifted Form: Height: 5′2″–6′0″; Weight: 110–180 lbs; slender build; russet-tinged hair; amber eyes with low-light gleam; slightly pointed ears. Animal Form: Length: 18–24 in body + 12–18 in tail; Height (shoulder): 12–16 in; Weight: 8–15 lbs; dense fur; narrow muzzle; large ears. Hybrid Form: Height: 5′4″–6′2″; Weight: 130–200 lbs; fox-like ears; tail; sharper facial structure; fur on arms/shoulders. Empowered Hybrid Form: Height: 5′6″–6′4″; Weight: 140–210 lbs; defined musculature; elongated claws.', 'Vulpine Shift-Folk display a poised, watchful demeanor, often moving with a light, deliberate step. Clothing favors flexibility and concealment, with subtle accents that echo their heritage. In animal or hybrid form, their posture balances readiness to spring with smooth, calculated motion.', '15-90', 15, 90, 'Medium', 2, 'Urban Fox’s Cunning', 'Gain +10 to the next Investigation or Networking roll that exploits a discovered clue.', 'Misdirection imposes –10 on their own next related roll.', 'Common', 'Cybersecurity Analyst; Investigative Journalist; Market Trend Researcher', 'Fantasy: A court informant who slips through noble intrigues to uncover plots before they hatch. Sci-Fi: A data-weaver in a megacity’s network underbelly, piecing together corporate secrets from stray code fraG.O.Dents. Post-Apocalyptic/Modern: A roamer who brokers information between survivor enclaves, trading knowledge for protection and supplies.', 'They treat information as both currency and weapon, relying on cunning, adaptability, and timing to achieve their goals. Vulpine Shift-Folk are keen observers, reading situations and people with an instinct for hidden motives. Their charm is often deliberate, a means to disarm before they strike—whether with words, actions, or both. While they can be fiercely loyal to those they trust, they rarely reveal the full depth of their intentions. To them, the clever path is always preferable to the direct one.', 'Magic is seen as the ultimate dataset—chaotic but patterned, waiting for the one sharp enough to decode it.'),
  (40, 'race-da84be7db929514acafebaf0ab916978358e67eebc6bf0a39d896599b0842410', 'Shift-Folk (Serpentine)', 'Descended from ancient serpent lineages, these shapeshifters embody patience, precision, and an unblinking awareness of their surroundings. In their unshifted form, they move with a subtle, sinuous grace, every motion measured and efficient. Serpentine folk excel in environments where heat, shadow, and silence dictate survival—humid basements, tunnel vents, and geothermal shafts become their natural hunting grounds. Their cultures prize stillness and observation, often placing great value on the art of waiting for the exact right moment to act. From early childhood, they are taught to read both their surroundings and the body language of others with uncanny accuracy, able to sense tension in a room as easily as they can track the warmth of a hidden body. This quiet vigilance makes them formidable trackers and protectors, as well as specialists in infiltration or recovery work. Social interactions are often deliberate and layered, with meaning conveyed in glances, pauses, and subtle shifts of tone. Among their own kind, a bond of trust is formed through shared watches and silent cooperation, while outsiders may find their calm intensity either captivating or unnerving. When threatened, their transformations awaken instincts honed by predator ancestry, bringing fluid speed, heightened senses, and dangerous precision to every strike. Whether navigating political intrigues, recovering long-lost relics, or defending their home tunnels from invaders, the Serpentine never act rashly—they strike only when the outcome is certain.', 'Unshifted Form: Height: 5′4″–6′2″; Weight: 130–220 lbs; lithe build; scaled patches on arms/torso; slit-pupil eyes. Animal Form: Length: 4′0″–12′0″; Weight: 15–150 lbs; muscular body; heat-sensing pits; camouflaged scales. Hybrid Form: Height: 5′6″–6′6″; Weight: 150–230 lbs; humanoid torso with serpentine lower body or scaled limbs; slit pupils. Empowered Hybrid Form: Height: 5′8″–6′8″ (or longer in full-tail form); Weight: 170–260 lbs; full-body scales; elongated tail.', 'Serpentine Shift-Folk stand with upright yet fluid posture, maintaining controlled, measured movements. Clothing is close-fitting to allow silent movement. In hybrid or animal forms, their motion is smooth, coiling, and precise, minimizing unnecessary motion until the exact moment of action.', '25-700', 25, 700, 'Medium', 2, 'Thermal Ambush', 'They pinpoint a living heat source or silent threat, gaining +10 to the next Perception or Investigation roll.', 'Thermal read is scrambled, suffering –10 on their next Perception or Investigation roll.', 'Common, Elven High-Cant', 'Thermal-Drone Operator; Artifact Recovery Tech; Exotic-Vet Handler', 'Fantasy: A temple guardian who watches from the shadows, striking only when intruders cross forbidden thresholds. Sci-Fi: A stealth operative using thermal imaging and serpentine grace to infiltrate hostile research facilities. Post-Apocalyptic/Modern: A scavenger navigating collapsed geothermal plants, tracking prey through heat signatures to secure scarce resources.', 'Patient, precise, and intensely aware of their surroundings, they favor observation before action. Serpentine Shift-Folk often let others reveal their intentions first, striking only when the outcome is certain. They are skilled at waiting out both conflict and negotiation, using time as a silent ally. While some find their stillness unsettling, it is simply the outward expression of careful calculation. To them, the best move is the one that ends the game in a single stroke.', 'Magic is perceived as a rhythmic pulse in the land—neutral until understood; mastery comes only when they can align that pulse with the flow of their own coil.'),
  (41, 'race-b053e53d78fcc4923c188eff6ec0506bd2caa8dde58843af828914be007ed42e', 'Shift-Folk (Lagomorph)', 'Descended from the swift and vigilant hare, these shapeshifters are built for speed, awareness, and survival in open or semi-open environments. In their unshifted form, they possess a lean, athletic frame and an energy that seems always poised to move, whether in conversation or in flight. Lagomorph folk are known for their wide-angle vision and fast-twitch reflexes, able to detect and react to threats before others have even turned their heads. Their culture prizes communal safety above all, often nesting in close-knit warren-like neighborhoods where news and warnings spread as swiftly as their steps. While cautious by nature, they are also capable of sudden, decisive bursts of action—whether to escape danger, deliver a critical message, or seize a fleeting opportunity. Social bonds are strengthened through trust and rapid information exchange, making them adept at relay work, scouting, and hazard reporting. Lagomorph traditions often teach that life is a series of “sprints” between safe havens, and that wisdom lies in knowing when to run and when to freeze. This philosophy informs everything from their emergency drills to their cooperative problem-solving. Outsiders may see them as overly jumpy, but those who underestimate their precision timing and endurance do so at their peril. When Transformation awakens, their already remarkable speed and perception sharpen into truly extraordinary tools, allowing them to outrun danger and navigate complex environments with ease.', 'Unshifted Form: Height: 4′6″–5′6″; Weight: 80–120 lbs; lean/agile build; long ears; large eyes. Animal Form: Length: 16–20 in; Weight: 3–6 lbs; powerful hind legs; patterned fur. Hybrid Form: Height: 4′8″–5′8″; Weight: 90–130 lbs; hare ears; fur along forearms/calves; elongated lower limbs. Empowered Hybrid Form: Height: 5′0″–6′0″; Weight: 100–140 lbs; increased leg/core musculature; longer ears/tail.', 'Lagomorph Shift-Folk keep a slightly crouched, spring-ready posture, with frequent shifts in ear and head position for situational awareness. Clothing is lightweight and flexible, designed for maximum movement. In hybrid or animal forms, their movements are quick, precise, and built for sudden acceleration.', '10-100', 10, 100, 'Medium', 2, 'Burst Reflex', 'Gain +10 to the next Dodge or escape-related check.', 'Stumble in the sprint—incur –10 on the next Dodge or escape check.', 'Common, plus one regional folk dialect', 'Medical Specimen Courier; Trackside Videographer; Ergonomic Tester', 'Fantasy: A village sentinel who spots distant threats and relays warnings before danger arrives. Sci-Fi: A courier darting through crowded spaceports to deliver fragile medical samples in record time. Post-Apocalyptic/Modern: A survival runner carrying critical intel between scattered settlements through hostile terrain.', 'They value communal safety, readiness, and quick response, measuring success by how swiftly danger is seen and acted upon. Lagomorph Shift-Folk rely on awareness and speed to keep themselves and their kin ahead of threats. They prefer to avoid unnecessary risks, yet are capable of sudden bursts of decisive action when the need arises. Their networks are built on trust and shared vigilance, with every member contributing to the watch. To them, survival is a race where foresight is the first step to winning.', 'Magic is viewed with excitement and caution—an unpredictable current to be mapped quickly and shared for the good of the warren.'),
  (42, 'race-a638e90999f0781ab8d130a3c9bbf22416fd8ff7a01ee2d81055b8c702e365ee', 'Shift-Folk (Piscine)', 'Descended from the bloodlines of sharks, dolphins, and other apex aquatic hunters, these shapeshifters are equally at home in the crushing depths or in flooded urban canals. In their unshifted form, they already display adaptations for life in the water—webbed fingers and toes, streamlined musculature, and gill slits that hint at their true heritage. Piscine folk thrive in the liminal spaces between sea and land, often taking up work in submerged tunnels, tidal spillways, and other places where few others can operate. Their societies value precision, timing, and the steady discipline required to survive in an environment where currents, pressure, and visibility can change in an instant. Oral histories and cultural songs are often transmitted through rhythmic clicks, pulses, and tonal patterns—many adapted into the Aquan Cant used by deep-water crews. Calm under pressure, they are known to keep working long past the point where others would panic, relying on practiced motions and instincts to guide them. Yet, beneath that calm lies a predator’s focus; when provoked, their strikes are decisive and often overwhelming. To them, the ocean is not just a home but a living, shifting map of resources, routes, and dangers, one they read as naturally as others read a city street. While they move with practiced skill on land, they consider dry environments inherently unstable, preferring to keep one foot—figuratively or literally—in the water at all times. When Transformation awakens, their aquatic prowess is magnified beyond natural limits, allowing them to become true masters of the depths.', 'Unshifted Form: Height: 5′2″–6′0″; Weight: 130–220 lbs; sleek build; webbed digits; subtle gill slits; eyes: slate or aquamarine. Animal Form: Length: 4′0″–8′0″; Weight: 80–300 lbs; streamlined aquatic body with fins and tail. Hybrid Form: Height: 5′4″–6′2″; Weight: 150–240 lbs; humanoid upper body; dorsal fin; scaled/rubbery skin; tail/flukes. Empowered Hybrid Form: Height: 5′6″–6′4″; Weight: 170–260 lbs; fully developed aquatic physiology; enhanced musculature.', 'Piscine Shift-Folk stand with relaxed posture and subtle body sway, adjusting balance as if compensating for water movement. Clothing is fitted and water-shedding, often adapted for both land and aquatic work. In hybrid or animal forms, they move with smooth, gliding motion, conserving energy for bursts of speed or maneuvering.', '15-90', 15, 90, 'Medium', 2, 'Hydrostatic Clarity', 'See through murk—gain +10 to next Perception or Investigation roll underwater.', 'Refraction misleads—take –10 on next related roll.', 'Common; Aquan Cant (click-pulse creole of deep crews)', 'Underwater Structural Welder; Tidal Energy Technician; Marine Film Stunt Diver', 'Fantasy: A reef-guard who patrols enchanted undersea grottos and wards against abyssal threats. Sci-Fi: A deep-space colony diver repairing tidal generators on a water-world. Post-Apocalyptic/Modern: A flood-zone salvager navigating submerged cities to recover vital infrastructure components.', 'They value precision, patience, and adaptation to shifting environments, preferring steady, calculated actions over haste. Piscine Shift-Folk excel in navigating complex situations where conditions can change without warning, adjusting their approach as easily as altering a current. They are keenly aware of patterns, both in nature and in people, and use that awareness to anticipate outcomes. While they are not quick to commit, once they set their course they follow it with quiet determination. To them, moving with the flow is not surrender—it is strategy.', 'Magic is seen as a current moving through the world—watched carefully for surges or changes that could alter the balance of the seas.'),
  (43, 'race-c3bf7d850aaa17c4e5c8da6301aad2845c0a6f775b5d35bea3ec1a0cb0ae1574', 'Shift-Folk (Marsupial)', 'Descended from kangaroo and possum ancestry, these shapeshifters embody a blend of explosive power, balance, and practicality. In their unshifted form, they are agile and sturdy, with a readiness in their posture that suggests they are always prepared to leap into action—literally or figuratively. Marsupial folk are defined by their signature pouches, which they use to carry tools, supplies, or even delicate cargo over long distances without slowing their stride. Their culture emphasizes preparedness and cooperation, with every adult expected to carry gear or goods for the benefit of the group. They see the world in terms of “bounds,” breaking journeys into leaps—both physical and metaphorical—planning for each with keen observation and foresight. In urban or rural environments, they are valued for their ability to traverse terrain quickly, whether crossing rooftops, bounding over uneven ground, or navigating bustling streets with equal ease. Their prehensile tails serve as both counterbalance and an additional limb, aiding in climbing, bracing, or delivering a defensive strike. Social gatherings often involve competitive leaping games or demonstrations of tail dexterity, both for entertainment and skill-honing. While generally easygoing and dependable, they can become fiercely protective when a member of their community is threatened. When Transformation awakens, their leaps become monumental, their balance near-perfect, and their tails capable of delivering crushing blows or deftly manipulating tools mid-battle.', 'Unshifted Form: Height 4′0″–5′0″; Weight 100–160 lbs; compact, muscular legs; copper-toned skin or fur; pouch line visible under waist; hair/fur tawny to reddish-brown with lighter underbellies. Animal Form: Height 2′6″–5′0″ (shoulder); Weight 25–200 lbs; full kangaroo or possum build; powerful hind legs; padded tail; forward-facing pouch. Hybrid Form: Height 4′2″–5′2″; Weight 110–175 lbs; elongated legs; strong tail; fur along limbs; functional pouch. Empowered Hybrid Form: Height 4′4″–5′4″; Weight 120–190 lbs; muscular legs and tail; reinforced pouch structure.', 'Move with coiled-leg readiness and an upright balance aided by their tail. Clothing is often belted or layered to integrate with the pouch for tool and supply storage. In hybrid/animal forms, posture shifts to a forward balance for leaps, with tail assisting in counterweight and stability.', '12-100', 12, 100, 'Medium', 2, 'Pouch Savant', 'Recall and deploy any small tool from pouch, granting +10 to next Engineering, Medicine, or Survival roll.', 'Pouch straps tangle—impose –10 on next Engineering or Medicine roll.', 'Common', 'Urban Courier Hops; Night-Shift Line-Cook; City-Park Clean-Up', 'Fantasy: A frontier scout carrying healing supplies between distant outposts with bounding leaps over dangerous terrain. Sci-Fi: A vertical city courier delivering precision parts across megastructure levels. Post-Apocalyptic/Modern: A survivor ferrying medicine between settlements, leaping over debris and hazards that stop others in their tracks.', 'Practical, cooperative, and terrain-focused, they value readiness and the careful planning of each “bound” before it’s made. Marsupial Shift-Folk are resourceful in unpredictable environments, often carrying what they need and protecting what matters most with layered caution. They are quick to secure safe havens and routes, ensuring their group can retreat or advance as needed. While they can be cautious to a fault, their foresight often prevents missteps others might overlook. To them, survival is a matter of always knowing where the next safe landing will be.', 'Magic is approached like a challenging course to navigate—best leapt over or cleverly avoided.'),
  (44, 'race-75123d6d281f0fc1801a506790414d1839f51fd519c08a401e282f4ffeddda8f', 'Shift-Folk (Chelonian)', 'Descended from ancient turtle and tortoise lineages, these shapeshifters are living embodiments of patience, resilience, and endurance. In their unshifted form, they move with deliberate precision, their sturdy builds and steady pace reflecting a worldview that values persistence over haste. Chelonian folk often bear textured, carapace-like patterns on their skin and an almost immovable stance when they choose to hold their ground. Their culture is built around the idea that survival is not about speed, but about weathering the storms that others cannot. This philosophy is evident in their work and their interactions—whether reinforcing river jetties, carrying hazardous materials across treacherous routes, or guiding others through meditative practice. Slow to anger and slow to act without cause, they are nonetheless relentless when committed, carrying out tasks with a thoroughness few can match. Community roles are often chosen for their long-term benefit, with Chelonians serving as the stable foundation upon which others can rely. While they may be underestimated for their pace, their sheer durability—both physical and mental—makes them difficult to outlast in any contest of will. Outsiders often interpret their silence as stubbornness, but those who take the time to understand them find a deep well of wisdom and measured care. When Transformation awakens, their already formidable endurance and protective instincts become a near-impenetrable bulwark, making them the anchor in any storm.', 'Unshifted Form: Height 4′0″–5′0″; Weight 180–300 lbs; broad shoulders; sturdy limbs; skin with shell-like patterning. Animal Form: Length 2′0″–5′0″; Weight 50–500 lbs; turtle/tortoise body; heavy shell; thick limbs. Hybrid Form: Height 4′2″–5′2″; Weight 200–320 lbs; partial shell on back/shoulders; thicker skin; clawed hands. Empowered Hybrid Form: Height 4′4″–5′4″; Weight 220–340 lbs; full shell coverage; dense muscle mass.', 'Maintain a slow, deliberate gait and grounded stance. Clothing is adapted to fit over or around shell growths. In hybrid/animal forms, movements are steady and resistant to impact, prioritizing stability over speed.', '40-400', 40, 400, 'Medium', 2, 'Shellborn Endurance', 'Gain +10 to the next Constitution or Survival roll.', 'Shellweight drags—incur –10 on next Constitution or Survival roll.', 'Common', 'Hazardous-Material Courier; River-Jetty Reinforcement; Zen Meditation Coach', 'Fantasy: A fortress guardian who holds the gate through siege after siege. Sci-Fi: A deep-space colony worker maintaining high-pressure reactor seals. Post-Apocalyptic/Modern: A hazmat courier who delivers supplies through irradiated flood zones, unshaken by long exposure.', 'Patient, steady, and grounded, they believe in outlasting rather than outpacing challenges. Chelonian Shift-Folk move through life with deliberate care, conserving their energy for the moments that truly require it. They value resilience over speed, trusting in preparation and endurance to see them through adversity. Though their measured approach may seem slow to outsiders, it allows them to carry their goals forward without being easily swayed. To them, the sure path is always worth more than the swift one.', 'Magic is approached like the ocean’s tide—its currents are endured and studied, never rushed.'),
  (45, 'race-533882556377682259c7039158d2b94423d5713f88984b5d5a8b222e01fd1225', 'Shift-Folk (Primate)', 'Descended from ape and monkey ancestry, these shapeshifters combine the physical power of their lineage with the quick problem-solving minds of adaptable survivors. In their unshifted form, they carry themselves with an easy athleticism, their movements purposeful and precise whether climbing scaffolds, navigating crowded marketplaces, or balancing along narrow beams. Primate folk are masters of improvisation, using their environment creatively to solve problems, overcome obstacles, or gain an advantage in both work and conflict. Their culture values collaboration and shared ingenuity, with knowledge often passed down through demonstrations, group challenges, and practical application rather than formal instruction. They thrive in team environments where communication is as much physical as verbal, often supplementing speech with expressive gestures and facial cues. Many are driven by curiosity and the satisfaction of a challenge well met, willing to test themselves physically and mentally in equal measure. While generally sociable and approachable, they can be fiercely competitive when their abilities are called into question. Their natural agility and grip strength make them adept in environments where vertical movement is essential, and they rarely shy from heights or complex mechanical spaces. Outsiders often find their problem-solving style unconventional, but their solutions work—sometimes in ways no one else could have predicted. When Transformation awakens, their already formidable balance, coordination, and strength increase dramatically, making them near-unstoppable in both feats of athleticism and acts of quick ingenuity.', 'Unshifted Form: Height 5′0″–6′0″; Weight 110–200 lbs; muscular, agile build; dextrous hands; slight brow ridge; fine hair on forearms/shoulders. Animal Form: Height 1′8″–4′6″ (shoulder); Weight 10–200 lbs; ape/monkey build; strong upper body; prehensile grip. Hybrid Form: Height 5′2″–6′2″; Weight 120–210 lbs; extended reach; partial fur; increased grip strength. Empowered Hybrid Form: Height 5′4″–6′4″; Weight 130–220 lbs; larger muscle mass; refined reflexes.', 'Carry themselves with upright confidence and smooth, controlled movement. Clothing often includes reinforced gloves or wrist wraps for climbing. In hybrid/animal forms, posture adapts for vertical mobility, with increased use of arms for propulsion and grip.', '15-90', 15, 90, 'Medium', 2, 'Primal Ingenuity', 'Improvise a solution, granting +10 to next Engineering, Innovation, or Athletics roll.', 'Overthinking causes hesitation—–10 on next relevant roll.', 'Common', 'Vertical Farm Harvester; Stunt Coordinator; Biomechanics Lab Aid', 'Fantasy: A siege engineer who climbs fortress walls to dismantle enemy engines mid-battle. Sci-Fi: A zero-G repair specialist using magnetic gloves and tail-mounted tools to fix rotating satellite systems. Post-Apocalyptic/Modern: A scavenger who swings between ruined high-rises to recover rare machinery.', 'Collaborative, inventive, and physically resourceful, they value creative solutions and shared success. Primate Shift-Folk are natural problem-solvers, often blending physical ability with clever improvisation. They thrive in environments where cooperation and quick thinking are equally rewarded. While they can be competitive within their circles, that rivalry often drives innovation rather than division. To them, the best outcome is one where the whole group benefits from the effort.', 'Magic is viewed as another system to dissect, adapt, and integrate into tools or technology.'),
  (46, 'race-4fd6cc318c747ff7e2731cdcfab0472fa4d032df9a0a9095753ebf06bc2440f4', 'Shift-Folk (Anuran)', 'Descended from frog and toad ancestry, these shapeshifters excel in environments where water and land intertwine. In their unshifted form, they display subtle amphibian traits—smooth, slightly damp skin, wide-set eyes, and an alert posture ready to leap into action. Anuran folk thrive in wetlands, storm drains, and riverfront ruins, where their knowledge of currents, water pressure, and surface tension gives them an edge in both survival and problem-solving. Their cultures place high value on environmental awareness, teaching members from a young age to “read” the water for changes in flow, clarity, and even smell. These skills make them excellent scouts, rescuers, and inspectors of critical water infrastructure. Social life often centers around shared vigilance, as shifts in water levels or quality can signal danger to the entire community. Their adhesive toe pads and flexible joints give them a physical confidence in vertical and slippery environments where others might hesitate. Though patient by nature, they can react with startling speed when opportunities or dangers present themselves. Outsiders often underestimate their adaptability, but those who work alongside them quickly learn the value of their precise environmental sense. When Transformation awakens, their leaping power, climbing ability, and aquatic agility reach extraordinary levels, allowing them to dominate both flooded spaces and vertical terrain.', 'Unshifted Form: Height 3′6″–4′6″; Weight 90–140 lbs; smooth skin (green/brown/gray); webbed fingers/toes; large, wide-set eyes. Animal Form: Length 4–12 in (body) + legs; Weight 1–15 lbs; frog/toad build; muscular hind legs; adhesive toe pads. Hybrid Form: Height 3′8″–4′8″; Weight 95–145 lbs; partial webbing; textured skin; enlarged eyes. Empowered Hybrid Form: Height 4′0″–5′0″; Weight 100–150 lbs; stronger hind legs; full adhesive digits.', 'Hold a slightly crouched stance with alert head and eye movement. Clothing is light and water-tolerant. In hybrid/animal forms, movements are spring-loaded for leaps or swimming bursts, often clinging to vertical or slick surfaces.', '12-60', 12, 60, 'Medium', 2, 'Waterlogged Clarity', 'Read water currents and vibrations, granting +10 to the party’s next Survival, Investigation, or Navigation roll.', 'Disoriented by eddies—–10 on own next related roll.', 'Common plus one aquatic dialect (Aqual Cant)', 'Dam Wall Inspector; Storm-Drain Rescuer; Parkour Instructor', 'Fantasy: A canal-runner who carries urgent missives along the waterways of a sprawling city-state. Sci-Fi: A maintenance diver who navigates coolant channels in a fusion plant. Post-Apocalyptic/Modern: A flood-zone rescuer skilled at navigating submerged streets to locate trapped survivors.', 'Attentive, adaptable, and highly aware of environmental changes, they see every shift in current or climate as a story to be read. Anuran Shift-Folk use this awareness to predict events before they happen, whether in nature or in social currents. They are quick to change tactics when conditions shift, often thriving where others struggle to keep pace. While they can seem restless, their movements are always purposeful. To them, survival is about timing the leap to match the moment.', 'Magic is perceived as a fluid force—channeled, redirected, and reinforced like water in a floodgate.'),
  (47, 'race-91fb21dabc4620247a27a2f46473027b11502e89313d7a9356e608c262759c47', 'Shift-Folk (Carapace)', 'Descended from beetle and roach ancestry, these shapeshifters are built for resilience in hostile environments. In their unshifted form, they carry a natural toughness that shows in their mottled, chitin-like skin and deliberate, grounded movements. Carapace folk thrive in industrial ruins, toxic sites, and hazardous terrain where others would quickly falter. Their culture values endurance, preparation, and the willingness to stand shoulder to shoulder when danger comes—traits that make them natural defenders and steady workers in high-risk settings. They are experts in reading the subtle signs of environmental hazards, from chemical traces in the air to the faint vibrations of approaching threats. While not known for their speed, they excel at holding ground and weathering both physical and environmental assaults. Social structures often mimic the interconnected strength of an insect colony, with communal resources and coordinated efforts forming the backbone of daily life. Outsiders may see them as overly cautious, but within their own ranks, such caution is regarded as wisdom bought by survival. Many carry the lingering scents of the places they’ve worked—traces of oils, metals, or dust—which serve as badges of endurance rather than stains to be washed away. When Transformation awakens, their armor hardens further, their strength surges, and they become living bulwarks capable of withstanding devastating blows and environmental extremes alike.', 'Unshifted Form: Height 4′6″–5′6″; Weight 180–300 lbs; stocky; mottled chitin-like skin; seG.O.Dented back/shoulders. Animal Form: Length 1′0″–2′6″; Weight 2–12 lbs (small beetles) to 150+ lbs (giant roaches); thick armored plating; strong mandibles. Hybrid Form: Height 4′8″–5′8″; Weight 200–320 lbs; partial carapace plates; seG.O.Dented limbs; compound eyes. Empowered Hybrid Form: Height 5′0″–6′0″; Weight 220–340 lbs; full chitin coverage; dense body mass.', 'Maintain a grounded, deliberate stance with minimal sway. Clothing is adapted to avoid catching on carapace ridges. In hybrid/animal forms, movements are solid and momentum-heavy, with a focus on impact absorption and anchoring.', '18-80', 18, 80, 'Medium', 2, 'Carapace Guard', 'Hardened shell grants +10 to next Constitution or Survival roll when resisting poison or shock.', 'Plate fissures or scent lingers—–10 on next Constitution or Survival roll.', 'Common, Draconic Trade Pidgin', 'Waste-Site Remediator; Forensic Scent-Tracker; Urban Spelunker', 'Fantasy: A dwarven vault guard who stands immovable against magical and physical assaults. Sci-Fi: An industrial hazard specialist repairing reactor leaks in deep-space mining stations. Post-Apocalyptic/Modern: A toxic-zone explorer leading salvage crews through long-contaminated ruins.', 'Enduring, cautious, and cooperative, they value preparation and collective defense above individual glory. Carapace Shift-Folk believe that strength lies in the group’s ability to protect itself, not in one member’s ability to stand alone. They excel in building and fortifying safe spaces, whether physical or social. While they may be slow to take risks, they are unwavering when the safety of their own is threatened. To them, defense well-kept is victory already half-won.', 'Magic is viewed as a volatile solvent—capable of stripping even the strongest shell unless carefully reinforced with protective runes.'),
  (48, 'race-272c906b501b97f896d005b1d3a27fc0f349dcfc76c35e58fff1f02ea0f48050', 'Shift-Folk (Rodentine)', 'Descended from porcupine and hedgehog ancestry, these shapeshifters are natural masters of self-defense and patient endurance. In their unshifted form, they display a sturdy frame and cautious manner, often keeping to the edges of a room or passage where they can see without being seen. Their retractable quills are a visible reminder that while they prefer to avoid conflict, they are never unarmed. Rodentine folk make their homes in subterranean warrens, sewer systems, and scrapyard tunnels, creating secure, defensible spaces that protect their communities from both physical and magical threats. They value vigilance and slow, deliberate action over rashness, favoring preparations that ensure their survival in the long term. Social customs often involve ritualized greetings that display or partially extend quills—an unmistakable sign of readiness that helps distinguish friend from foe. Many have a knack for working with their environment, turning discarded materials into useful tools or defensive structures. While they may appear reserved to outsiders, those who earn their trust find loyal allies who will stand their ground against overwhelming odds. Their nocturnal tendencies give them an advantage in low-light environments, allowing them to navigate and defend their homes with ease. When Transformation awakens, their quills become deadlier, their reflexes sharper, and their resilience nearly unmatched.', 'Unshifted Form: Height 3′0″–4′0″; Weight 80–140 lbs; earth-tone fur; clawed hands/feet; retractable quills along back/arms/scalp. Animal Form: Length 8–20 in body + tail; Weight 2–35 lbs; porcupine/hedgehog build; dense quills; short limbs. Hybrid Form: Height 3′2″–4′2″; Weight 85–150 lbs; partial quill coverage; enhanced digging claws. Empowered Hybrid Form: Height 3′4″–4′4″; Weight 90–160 lbs; fully hardened quills; robust frame.', 'Favor cautious, slightly hunched postures to protect vulnerable areas. Clothing is loose or seG.O.Dented to accommodate quill extension. In hybrid/animal forms, movements are careful but can shift quickly into defensive bracing or close-range quill strikes.', '10-100', 10, 100, 'Medium', 2, 'Spiny Aegis', 'Quills deflect harm—gain +10 to next Constitution roll resisting damage.', 'Quills stiffen awkwardly—–10 on next Dexterity or Constitution roll.', 'Common, Under-city Cant', 'Armored Bike Courier; Tree-Pruning Spike Climber; Personal-Security Guard', 'Fantasy: A city’s underpass sentinel who fends off thieves and smugglers. Sci-Fi: A deep-space maintenance worker who uses quills as both a defensive measure and an improvised toolkit. Post-Apocalyptic/Modern: A tunnel network defender who patrols subway ruins, using quills to deter mutant predators.', 'Cautious, resourceful, and defense-oriented, they place community safety above individual risk. Rodentine Shift-Folk are masters at securing resources and safeguarding them for leaner times. They are quick to notice when something is amiss, and even quicker to alert others. While they may retreat from danger rather than face it head-on, they do so to preserve the group’s strength for when it’s truly needed. To them, survival is a shared burden, best shouldered together.', 'Magic’s resurgence is approached with guarded praG.O.Datism, weaving arcane wards into tunnel walls and quills tuned to vibrate in response to magical intrusion.'),
  (49, 'race-90f7c85de46d06a4b26128b85c901f95f8188b7e299043626540b08ce49cf971', 'Féarai Elves', 'Once the soaring custodians of vast archives, Féarai Elves dedicated their lives to preserving and expanding the world’s collective knowledge. In ages past, they traveled between great repositories of lore, recording events, discoveries, and philosophies with meticulous care. Their neon-hued wings and luminescent eyes made them as striking in appearance as they were precise in thought. They believe the world itself is a living manuscript, with every action a sentence and every lifetime a chapter, and they see themselves as both authors and protectors of that grand story. When the flow of magic waned, their wings lost the lift needed for flight, and entire generations withdrew into deep, protected vaults, entering long periods of dormancy to safeguard their knowledge until the arcane currents returned. Their societies place great emphasis on truth, accurate memory, and the defense of recorded history against distortion or corruption. Playful in manner but serious in purpose, they weave scholarship into art and conversation alike, ensuring information is both preserved and shared. They train from youth to memorize vast amounts of data, cross-referencing facts instinctively and recalling them with remarkable precision. With the return of magic, they have reemerged from their hidden vaults, determined to update the archives and prevent misinformation from altering the story of the present age. Their presence is often a sign that history is being written in the moment.', 'Average Height: 3′6″–4′0″; Average Weight: 55–70 lbs; Wingspan: ~1.2 m; Build: slender, small-framed; Skin: varied natural elf tones; Hair: varied, often fine-textured; Eyes: large, patterned like intricate script; Wings: translucent gossamer with neon iridescence; Other: faint kaleidoscopic body glow that shifts subtly with mood or ambient magic.', 'Small, luminous-winged elves with delicate frames and eyes that seem to hold written patterns. Their wings shimmer like stained glass in sunlight, and their natural luminescence lends them a subtle, shifting glow. They tend to dress in finely layered garments that move with the air, often incorporating script-like patterns in embroidery or dye. Movements are light and precise, with a habit of tilting their heads when listening, as if weighing each word.', '30-400', 30, 400, 'Small', 5, 'Mnemonic Snapshot', 'Extract perfect reference—+10 to the party’s next Academics, Arcana, or Strategy roll and halve related research time.', 'Mental indexing misfires—–10 on own next Intelligence-based roll.', 'Common, Scriptura Cant (librarian cipher)', 'Pan-Sphere Librarian; Field Research Custodian; Prismatic Trickster-Scholar', 'Fantasy: A skybound archivist who records unfolding events in real time, shaping future histories. Sci-Fi: A data-preserver who translates alien histories into universal formats. Post-Apocalyptic/Modern: A roving scholar safeguarding oral histories of survivor communities.', 'They view the world as a living manuscript, each event another line in the ongoing story they safeguard. Playfulness blends with dedication to truth, making them both storytellers and keepers of history. They are wary of distortion—whether deliberate or accidental—and work to preserve knowledge in its purest form. While they enjoy weaving tales, they rarely embellish when it would alter meaning, believing that the truth is compelling enough on its own. To them, memory is a gift, and the careful tending of it is a sacred duty.', 'Magic’s resurgence is seen as both opportunity and responsibility—to expand the archive and protect its integrity.'),
  (50, 'race-0221fe4ce55b7fd58714ac26b2813300e4df9ba14daa0d2c652a9eaecaf67b90', 'Gold Naga Orang', 'Descended from a proud lineage of drake-folk, the Gold Naga Orang once served as emissaries, protectors, and lore-keepers for dragonkind across many realms. Their ember-coil hearts burned with an inner fire said to connect them directly to the essence of their progenitors. In times of abundance, they maintained high vaults and spires where memory was recorded not just in writing, but in living tradition, with each generation trained to embody both the knowledge and dignity of their role. When the flow of magic waned, their hearts dimmed, and entire broods sealed themselves within basalt incubation halls, wrapped in protective limestone chrysalis scales to await the rekindling of the arcane winds. They value ceremony and precision, believing that actions carry weight beyond the moment and should be performed with intent. Their society is hierarchical yet deeply bonded, with elder mentors guiding the growth of younger generations in both skill and moral discipline. Gold Naga Orang are known for balancing restraint with decisive action—calm in council, fierce in defense. Outsiders often find them imposing due to their stature, polished scales, and unwavering focus, but those who earn their trust find loyal allies. With the return of magic, their ember-coils reignite, awakening both their draconic breath and their sense of purpose. In every age, they have been seen as living bridges between mortal peoples and the great dragon flights.', 'Average Height: 6′2″–7′0″; Average Weight: 280–360 lbs; Wingspan: 16–18 ft; Build: upright, muscular frame; Skin: golden scales with metallic sheen; Eyes: pale amber; Wings: pale amber membrane; Tail: heavy, clubbed, 4–6 ft in length; Hands/Feet: clawed digits, taloned toes.', 'Tall, broad-shouldered draconic humanoids with golden scales that gleam in the light and large, pale amber wings. Their posture is upright and commanding, with a deliberate economy of motion. Clothing and armor often highlight their metallic hues, and they favor regalia that reflects their heritage. The tail is used as both a counterbalance and a visible statement of strength.', '30-400', 30, 400, 'Medium', 1, 'Sky-Lever Momentum', 'Translate air-brake lift into speed; next movement check +10.', 'Mis-judged draft → –10 on next movement-related roll.', 'Common, Draconic Glyph Cant', 'Vault Sentinel; Sky Bridger; Breath-Smith', 'Fantasy: A golden-winged guardian who defends a mountaintop archive from would-be thieves. Sci-Fi: A planetary envoy from a draconic heritage station, bridging disputes with authority and presence. Post-Apocalyptic/Modern: A lone drake-blooded wanderer who guards the last remnants of dragon lore in a crumbling city.', 'They value ceremony, discipline, and the preservation of heritage, balancing restraint with decisive defense. Gold Naga Orang see themselves as protectors of tradition, ensuring that the past’s wisdom guides the present’s actions. They are deliberate in both speech and movement, using formality to convey respect and intent. While they may appear rigid, they can act with startling swiftness when the moment demands it. To them, honor is not a posture but a practice—something proven through consistent action.', 'Magic’s return is embraced as both a personal rekindling and a chance to reunite with dragonkind.'),
  (51, 'race-782178210948b2d316bfe06106662016b305c5ca6637465d7e6377570c010ff5', 'Red Naga Orang', 'Sharing the proud drake-folk lineage of the Gold Naga Orang, the Red Naga Orang are known for their boldness, commanding presence, and mastery of fire-breathing techniques. In ages past, they served as both guardians and envoys, often taking the lead in negotiations where strength and charisma held equal weight. Their ember-coil hearts burned bright, and they were as comfortable in the high vaults of dragonkind’s strongholds as they were on the open field of battle. When the mana currents faltered, they followed their kin into basalt incubation halls, preserving their lineage in dormancy until the arcane winds returned. Reds hold a deep respect for ceremonial structure, yet are more direct in action than some of their cousins, preferring decisive strikes to prolonged deliberation. Their society prizes eloquence as much as martial skill, and many Red Naga Orang act as spokespeople or defenders of their people’s honor. They view challenges as opportunities to demonstrate both their strength and their ability to lead. With magic’s resurgence, their ember-coils reignite, bringing back the full force of their fire-breath and the resonating power of their fearsome roars. In all realms, they are recognized as figures of authority, courage, and tradition.', 'Average Height: 6′2″–7′0″; Average Weight: 280–360 lbs; Wingspan: 16–18 ft; Build: upright, muscular frame; Skin: crimson scales with darker shading on limbs; Eyes: molten amber; Wings: dark red membrane; Tail: thick, heavy, 4–6 ft in length; Hands/Feet: clawed digits, taloned toes.', 'Broad, powerfully built draconic humanoids with deep crimson scales and dark membrane wings. Their presence is forceful, and they carry themselves with the assurance of natural leaders. Armor and clothing are often cut to display wing joints and shoulders, and their tails sway in subtle rhythm when assessing a situation.', '30-400', 30, 400, 'Medium', 1, 'Sky-Lever Momentum', 'Translate air-brake lift into speed; next movement check +10.', 'Mis-judged draft → –10 on next movement-related roll.', 'Common, Draconic Glyph Cant', 'Vault Sentinel; Sky Bridger; Breath-Smith', 'Fantasy: A flame-winged commander leading a defense of a cliffside fortress. Sci-Fi: A planetary governor resolving disputes between human and draconic colonies. Post-Apocalyptic/Modern: A community leader defending the last dragon shrine from raiders.', 'Value strength, leadership, and decisive action within a ceremonial framework.They value strength, leadership, and decisive action within a ceremonial framework. Red Naga Orang are natural commanders, willing to shoulder the risks of leadership when others hesitate. They see challenges as opportunities to prove their mettle, both to themselves and to their people. While they respect tradition, they will adapt it if doing so ensures survival or victory. To them, leadership is not a privilege, but a responsibility to guide others through both glory and hardship.', 'Magic’s return is both a rekindling of personal power and a renewal of their role as protectors and negotiators for dragonkind.'),
  (52, 'race-bc1bc03b81aba6f2ed765fbde3198862dcf51eaece5872ce14a3a53aee21176d', 'Black Naga Orang', 'The Black Naga Orang are among the most feared and mysterious of the drake-folk, their dark scales and piercing gaze evoking both awe and unease. Like their kin, they once served in the high vaults as lore-keepers and guardians, their ember-coil hearts attuned to the will of dragonkind. In the days before the mana waned, they often took on roles requiring subtlety and endurance—tasks where patience and precision were valued above open display. When the magical tides receded, they entered the same basalt halls of dormancy as their cousins, waiting for the right moment to awaken. Black Naga Orang tend toward a reserved demeanor, speaking little but acting with decisive force when called upon. Their reputation for unwavering resolve is matched by their resilience in hostile environments, a trait that has made them both formidable warriors and trusted sentinels. The return of magic reignites their strength, sharpening their abilities and awakening the corrosive power of their acid breath. They embody the saying that true power does not need to shout—it is simply known.', 'Average Height: 6′2″–7′0″; Average Weight: 280–360 lbs; Wingspan: 16–18 ft; Build: broad, heavy-set; Skin: black onyx scales with muted metallic sheen; Eyes: acid green; Wings: dark membranes with green-veined patterns; Tail: thick, heavy, 4–6 ft in length; Hands/Feet: clawed digits, taloned toes.', 'Broad-shouldered draconic humanoids whose dark scales shimmer faintly under light. The acid-green wing veins catch the eye when they move. Their gaze is steady and often unblinking, and they wear minimal ornamentation beyond what is necessary for practical use.', '30-400', 30, 400, 'Medium', 1, 'Sky-Lever Momentum', 'Translate air-brake lift into speed; next movement check +10.', '–10 on next movement-related roll if failed.', 'Common, Draconic Glyph Cant', 'Vault Sentinel; Sky Bridger; Breath-Smith', 'Fantasy: A silent guardian patrolling the shadowed bridges of a dragon’s citadel. Sci-Fi: An infiltration specialist defending hidden archives within a draconic space station. Post-Apocalyptic/Modern: A lone black-scaled sentinel who watches over the ruins of a dragon temple.', 'They value patience, resolve, and precision, acting only when the outcome is certain. Black Naga Orang are masters of restraint, often preferring to let situations develop before intervening. This patience is not passivity, but a calculated choice to ensure their actions carry maximum effect. While they may seem slow to outsiders, those who underestimate them rarely get a second chance. To them, the perfect strike is one delivered at the exact moment it is needed—and not before.', 'Magic’s resurgence deepens their quiet strength and restores their role as unyielding sentinels of dragonkind’s legacy.'),
  (53, 'race-3751e78ad870a6595ee0e313f021440a32cc3f6ad3e536e90da2abaef98aa2de', 'Blue Naga Orang', 'Blue Naga Orang are drake-folk attuned to the forces of storm and sea, their lineage marked by a deep connection to lightning and the rolling rhythm of water. In the golden age of their kind, they served as navigators, storm-guides, and emissaries to coastal and skyborne dragon flights. Their ember-coil hearts pulsed in time with the tempests they commanded, their lightning breath feared and respected across many realms. When magic’s ebb came, they joined their kin in basalt incubation halls, trusting the storms would one day return to wake them. They value adaptability and clear judG.O.Dent, seeing life as a balance between calm waters and sudden storms. In council, they are thoughtful, weighing options carefully before acting; in conflict, they strike with a swiftness and precision that can end disputes before they escalate. With the return of magic, their ember-coils surge with renewed energy, restoring their lightning breath and their affinity for navigating both sea and sky. They are seen as heralds of change—often arriving just before a turning point in events.', 'Average Height: 6′2″–7′0″; Average Weight: 280–360 lbs; Wingspan: 16–18 ft; Build: lean but muscular; Skin: cobalt blue scales with oceanic shimmer; Eyes: bright blue; Wings: electric-blue membranes; Tail: balanced, 4–6 ft in length; Hands/Feet: clawed digits, taloned toes.', 'Sleek, balanced draconic humanoids whose cobalt scales ripple with shifting hues under different lighting. Their wing membranes glow faintly when spread. Clothing tends to be close-fitting for movement, with accessories suited for sea or sky travel.', '30-400', 30, 400, 'Medium', 1, 'Sky-Lever Momentum', 'Translate air-brake lift into speed; next movement check +10.', '–10 on next movement-related roll if failed.', 'Common, Draconic Glyph Cant', 'Vault Sentinel; Sky Bridger; Breath-Smith', 'Fantasy: A storm-winged envoy guiding ships safely to harbor. Sci-Fi: A lightning-wielding interceptor patrolling the skies of a floating city. Post-Apocalyptic/Modern: A blue-scaled wanderer who uses their powers to bring rain to drought-stricken lands.', 'They value adaptability, foresight, and precision, balancing patience with decisive action. Blue Naga Orang read situations much like navigators reading currents, shifting their approach to fit the flow of events. They are comfortable in uncertain conditions, using flexibility as a way to maintain control when others might flounder. Their planning often extends far ahead, but they keep enough fluidity to pivot when opportunity arises. To them, strength lies not in rigidity, but in the ability to act with purpose under shifting skies.', 'Magic’s resurgence restores their storm-born gifts and renews their role as guides and defenders of draconic heritage.'),
  (54, 'race-bde506aa79f3f2b156121de42a27bb1db6444bfad2fe9e3d1eeb222a2138dd9b', 'Silver Naga Orang', 'Among the drake-folk, the Silver Naga Orang are renowned for their grace, clarity of thought, and the quiet authority they carry into any gathering. In earlier ages, they served as mediators and trusted advisors, their cool composure making them ideal for resolving disputes between dragon flights and mortal peoples. Their ember-coil hearts burned steady rather than fierce, channeling their energy into long-term service and the preservation of alliances. When magic ebbed, they joined their kin in the basalt incubation halls, their silvered forms cocooned in frost-hardened shells awaiting the return of the ley currents. Silvers value trust, discretion, and the cultivation of stable relationships across generations. While they rarely seek the spotlight, their influence often shapes the course of events from behind the scenes. Their presence carries a calming effect, both in counsel and in battle, and they are known for defusing conflicts before they can erupt. With the resurgence of magic, their cold breath and diplomatic charm return in full measure, restoring their place as indispensable voices in matters of high importance.', 'Average Height: 6′2″–7′0″; Average Weight: 280–360 lbs; Wingspan: 16–18 ft; Build: tall, poised; Skin: silver-white scales with frosted edges; Eyes: luminous silver; Wings: pale silver membranes; Tail: balanced, 4–6 ft in length; Hands/Feet: clawed digits, taloned toes.', 'Elegant draconic humanoids with a calm, measured bearing. Their silvered scales and frosted wing edges reflect light in soft gradients. Clothing is often understated yet finely made, favoring fabrics that drape smoothly over their tall frames.', '100-1500', 100, 1500, 'Medium', 1, 'Sky-Lever Momentum', 'Translate air-brake lift into speed; next movement check +10.', '–10 on next movement-related roll if failed.', 'Common, Draconic Glyph Cant', 'Vault Sentinel; Sky Bridger; Breath-Smith', 'Fantasy: A silver-winged envoy who settles disputes between rival kingdoms. Sci-Fi: A diplomatic officer mediating between interstellar dragon enclaves. Post-Apocalyptic/Modern: A silver-scaled negotiator bringing peace to warring survivor factions.', 'They value trust, diplomacy, and long-term stability in relationships. Silver Naga Orang see agreements as living bonds, maintained through continued respect and mutual benefit. They work to build alliances that can weather both prosperity and hardship, believing that trust is as valuable as any resource. While they prefer peaceful resolution, they will defend these bonds fiercely if they are threatened. To them, loyalty is the true measure of worth, and betrayal is a wound that rarely heals.', 'Magic’s return renews their role as peacekeepers and trusted advisors among dragonkind.'),
  (55, 'race-924e9592a578873ba658ac8085a334a8cf4876d0c0f575f886eddef1645d2136', 'Brass Naga Orang', 'Brass Naga Orang are the warm-voiced heralds of the drake-folk, famed for their quick wit, open demeanor, and skill at turning conversation into opportunity. In the high vaults, they often served as heralds, diplomats, and cultural liaisons, carrying messages between dragon flights and mortal cities. Their ember-coil hearts burned with a steady, welcoming heat, and their words carried weight not through force, but through the trust they inspired. When the mana currents faded, they withdrew alongside their kin, sealing themselves in basalt chambers until the flow returned. Brass Naga Orang value connection, good humor, and the art of persuasion, seeing social bonds as the strongest form of armor. They are often the first to volunteer for envoy duties, navigating dangerous situations with charm and tact. With magic’s return, their breath once again carries the power of sleep, disarming threats without violence when possible. They are often seen as the heart of a group—bringing people together, diffusing tensions, and turning strangers into allies.', 'Average Height: 6′2″–7′0″; Average Weight: 280–360 lbs; Wingspan: 16–18 ft; Build: upright, approachable frame; Skin: brassy-gold scales with warm highlights; Eyes: amber; Wings: warm golden membranes; Tail: smooth, tapering, 4–6 ft in length; Hands/Feet: clawed digits, taloned toes.', 'Warmly colored draconic humanoids with an approachable, open demeanor. Their scales gleam with brassy warmth, and their expressions tend to be animated. Clothing and ornamentation are often colorful, complementing their metallic tones.', '100-1500', 100, 1500, 'Medium', 1, 'Sky-Lever Momentum', 'Translate air-brake lift into speed; next movement check +10.', '–10 on next movement-related roll if failed.', 'Common, Draconic Glyph Cant', 'Vault Sentinel; Sky Bridger; Breath-Smith', 'Fantasy: A brass-scaled envoy who charms their way into enemy courts to secure peace. Sci-Fi: A cultural liaison bridging human-dragon trade relations. Post-Apocalyptic/Modern: A mediator who uses their presence and voice to disarm tense standoffs.', 'They value diplomacy, connection, and the resolution of conflict without force. Brass Naga Orang are skilled negotiators, often finding solutions that leave all parties feeling heard and respected. They believe that most disputes can be resolved through careful listening and honest exchange, though they are not blind to situations where firmer measures are required. Their charm is matched by a sharp mind, making them persuasive without being manipulative. To them, every bridge built is stronger than a wall raised.', 'Magic’s return renews their gift for persuasion and non-lethal resolution.'),
  (56, 'race-bf507e799e1dd07a2d3a3412d85f55de8824f767235596f728ee917d6e3180f4', 'Grey Naga Orang', 'The Grey Naga Orang are the rare fusion of arcane mastery and martial discipline, descended from the primordial Grey Dragon’s lineage. They are swift, cunning, and adaptable, equally capable of leading in battle or guiding magical research. In their height, they commanded mountain aeries where both strategy and sorcery were taught, blending spellcraft with physical prowess to create an elite guard-scholar tradition. When the mana faltered, they withdrew into Aether-Shell cocoons atop high peaks, maintaining vigilance even in stasis. Greys value balance—tempering might with wisdom, and instinct with planning. They are natural leaders in both combat and counsel, rallying allies and outmaneuvering foes through a combination of quick thinking and decisive strikes. The return of magic reignites their primal plasma breath and restores their true flight, granting them full aerial maneuverability. Known for their discipline, they see themselves as stewards of responsible magic use, ensuring their power is never misused.', 'Average Height: 6′2″–7′0″; Average Weight: 280–360 lbs; Wingspan: 16–18 ft; Build: athletic, refined; Skin: gunmetal scales with silver sheen; Eyes: pale grey; Wings: smoky membranes; Tail: flexible, whip-like, 4–6 ft in length; Hands/Feet: clawed digits, taloned toes.', 'Streamlined draconic humanoids with balanced musculature and quick, precise movements. Their gunmetal scales catch light with a steel-like glint. They wear gear optimized for mobility, and their whip-like tails shift subtly to aid balance.', '100-1500', 100, 1500, 'Medium', 5, 'Draconic Insight', '+10 to next Spellcraft, Strategy, or Leadership roll.', 'Mental echo-overload → –10 on next Intelligence or Wisdom roll.', 'Common, Draconic Cipher', 'Aerie Marshal; Lore-Bearer; Strike Arbiter', 'Fantasy: A battle-mage commander leading aerial strikes against invading forces. Sci-Fi: A tactical operations leader defending a dragon-space citadel. Post-Apocalyptic/Modern: A grey-scaled arbiter who unites scattered survivors through strategy and example.', 'They value balance, discipline, and the union of arcane mastery with physical skill. Grey Naga Orang believe that true power comes from integrating mind, body, and spirit into a single, harmonious force. They train equally in mental focus and physical readiness, seeing the two as inseparable. Their calm demeanor masks a readiness to act with precision when the time is right. To them, mastery is not a goal to be reached, but a path to be walked for a lifetime.', 'Magic’s return restores their role as arcane-martial leaders and protectors of magical balance.');

INSERT OR IGNORE INTO races (
    name, legacy_description, physical_characteristics, physical_description,
    age_range_text, age_min, age_max, size, base_magic, racial_quirk_name,
    quirk_success_effect, quirk_failure_effect, common_languages_known,
    common_archetypes, genre_examples, cultural_mindset, outlook_on_magic,
    created_by_user_id, source_system, source_external_id
)
SELECT name, legacy_description, physical_characteristics, physical_description,
       age_range_text, age_min, age_max, size, base_magic, racial_quirk_name,
       quirk_success_effect, quirk_failure_effect, common_languages_known,
       common_archetypes, genre_examples, cultural_mindset, outlook_on_magic,
       NULL, 'serrian-tide-race-sheet', source_external_id
FROM _serrian_tide_race_seed
ORDER BY ordinal;

DROP TABLE IF EXISTS temp._serrian_tide_race_cap_seed;
CREATE TEMP TABLE _serrian_tide_race_cap_seed (
    ordinal INTEGER PRIMARY KEY,
    race_external_id TEXT NOT NULL,
    attribute_key TEXT NOT NULL,
    max_value REAL NOT NULL,
    sort_order INTEGER NOT NULL
);
INSERT OR IGNORE INTO race_attribute_caps (race_id, attribute_key, max_value, sort_order)
SELECT race.id, seed.attribute_key, seed.max_value, seed.sort_order
FROM _serrian_tide_race_cap_seed seed
JOIN races race
  ON race.source_system = 'serrian-tide-race-sheet'
 AND race.source_external_id = seed.race_external_id
ORDER BY seed.ordinal;

DROP TABLE IF EXISTS temp._serrian_tide_race_movement_seed;
CREATE TEMP TABLE _serrian_tide_race_movement_seed (
    ordinal INTEGER PRIMARY KEY,
    race_external_id TEXT NOT NULL,
    movement_mode TEXT NOT NULL,
    base_value REAL NOT NULL,
    notes TEXT NOT NULL,
    sort_order INTEGER NOT NULL
);
SELECT race.id, seed.movement_mode, seed.base_value, seed.notes, seed.sort_order
FROM _serrian_tide_race_movement_seed seed
JOIN races race
  ON race.source_system = 'serrian-tide-race-sheet'
 AND race.source_external_id = seed.race_external_id
WHERE NOT EXISTS (
    SELECT 1 FROM race_movement_modes existing
    WHERE existing.race_id = race.id
      AND existing.movement_mode = seed.movement_mode COLLATE NOCASE
)
ORDER BY seed.ordinal;

DROP TABLE IF EXISTS temp._serrian_tide_race_skill_seed;
CREATE TEMP TABLE _serrian_tide_race_skill_seed (
    ordinal INTEGER PRIMARY KEY,
    race_external_id TEXT NOT NULL,
    skill_external_id TEXT NOT NULL,
    link_type TEXT NOT NULL,
    value REAL,
    sort_order INTEGER NOT NULL
);
INSERT OR IGNORE INTO race_skill_links (race_id, skill_id, link_type, value, sort_order)
SELECT race.id, skill.id, seed.link_type, seed.value, seed.sort_order
FROM _serrian_tide_race_skill_seed seed
JOIN races race
  ON race.source_system = 'serrian-tide-race-sheet'
 AND race.source_external_id = seed.race_external_id
JOIN skills skill
  ON skill.source_system = 'serrian-tide-core'
 AND skill.source_external_id = seed.skill_external_id
ORDER BY seed.ordinal;

DROP TABLE _serrian_tide_race_skill_seed;
DROP TABLE _serrian_tide_race_movement_seed;
DROP TABLE _serrian_tide_race_cap_seed;
DROP TABLE _serrian_tide_race_seed;
